const e={protocols:{name:"SACAA Summarised Medical Protocols in line with Part 67 (effective 16 November 2021), item 52",url:"https://caasanwebsitestorage.blob.core.windows.net/avmed-amended-protocols/Summarised%20Medical%20Protocols%20in%20line%20with%20Part%2067%20of%20the%20Civil%20Aviation%20Regulations%20and%20Technical%20Standards.pdf"},classes:{name:"SACAA: amended Part 67 regulation 67.00.2, classes of medical certificates",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-general-information/Ammended%20%20Part%2067%20Regulations%20Classes%20of%20medical%20certificates.pdf"},application:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.7 (Application for medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_7_application.php"},class4:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.5 (Class 4 medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_5_class_4_med.php"},cabin:{name:"Civil Aviation Regulations, 2011, Part 64, regulation 64.01.6 (Cabin crew medical fitness)",url:"https://source.acts.co.za/civil-aviation-act-2009/nr425_64_01_6_medical_fit.php"},am007:{name:"SACAA procedure AM007: issuing of Class I, II, III and IV medical certificates (reissued 15 September 2025)",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/AM007%20Issuing%20of%20a%20class%20IIIIII%20and%20IV%20medical%20certificate.pdf"},avmed:{name:"SACAA Aviation Medicine page",url:"https://www.caa.co.za/industry-information/aviation-medicine/"},faq:{name:"SACAA Frequently Asked Questions (medical classes and validity periods, Class 4 for cabin crew, who may examine, extensions)",url:"https://www.caa.co.za/information-for-the-public/frequently-asked-questions/"},register:{name:"SACAA list of Regular Designated Aviation Medical Examiners (Dr AO Ndhlovu, MR 336)",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Regular%20DAMES.pdf"},form:{name:"SACAA form CA 67-02(a), Aviation Medical Report",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf"},classesReg:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.2 (Classes of medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_2_classes_of_.php"},designation:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.4 (Designation of aviation medical examiners)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_4_designation.php"},validityReg:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.6 (Period of validity and extensions)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_6_period_of_v.php"},issuing:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.8 (Issuing of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_8_issuing_of_.php"},duties:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.9 (Duties of holder of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_9_duties_of_h.php"},records:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.12 (Period of validity of medical records)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_12_period_of_.php"},suspension:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.14 (Suspension or cancellation of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_14_suspension.php"},spl:{name:"Civil Aviation Regulations, 2011, Part 61, regulation 61.02.1 (Requirements for SPL or ISPL, as amended 21 August 2026)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_61_02_1_requirements.php"}},i={slug:"renew-sacaa-class-2-medical",title:"Class 2 Medical Renewal, Step by Step | ClinoTrend",h1:"How to renew your SACAA Class 2 medical, step by step",description:"Renew a SACAA Class 2 medical in South Africa: when to book, which examiner, what to bring, what happens on the day, and how to apply for a 30 day extension.",excerpt:"When to book, which examiner can renew it, what to bring, what happens on the day, and what to do if your certificate is about to expire.",keyword:"class 2 medical renewal",question:"How do I renew my SACAA Class 2 medical?",answer:"Check the expiry date on your certificate, then book a SACAA Designated Aviation Medical Examiner a few weeks before it. Bring your ID, licence, current certificate, logbook and a list of your medicines. If you meet the standards, the certificate can be issued on the day. Apply to SACAA for an extension at least 15 days before expiry if needed.",facts:["Under Part 67, a Class 2 certificate is valid for 60 months if you are less than 40, 24 months after your 40th birthday, and 12 months after your 50th birthday.","Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book.","Dr A.O. Ndhlovu, SACAA Regular DAME MR 336, does Class 2 renewals at Grand Central Airport, Midrand."],secondary:["sacaa class 2 medical certificate","class 2 medical certificate south africa","sacaa medical extension","sacaa medical examiners"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Renewals",body:[{t:"p",x:"If you fly on a student pilot licence (SPL) or a private pilot licence (PPL), your licence is only valid while you hold a current Class 2 medical certificate. Renewing it is routine, but a little planning avoids a gap in flying. This guide walks through the renewal in the order you will meet each step, with the South African Civil Aviation Regulations (Part 67) quoted where it matters."},{t:"h2",x:"Who needs a Class 2 medical?",id:"who"},{t:"p",x:"Under the amended regulation 67.00.2 of Part 67, a Class 2 medical certificate covers, among others, the SPL, the PPL for aeroplane, airship and helicopter, the flight engineer licence, the free balloon commercial pilot licence and the commercial glider pilot. The same regulation says that a pilot holding a valid Class 1 certificate is deemed to hold a valid Class 2 and Class 4 certificate."},{t:"p",x:"Cabin crew may need a Class 2 or a Class 4 medical, depending on what the airline or operator asks for. If you are cabin crew, read our guide to [cabin crew medical requirements](/blog/cabin-crew-medical-class-4-south-africa/)."},{t:"h2",x:"How do I check my expiry date?",id:"expiry"},{t:"p",x:"Look at the expiry date printed on your current certificate. Certificates run to the **last day of a month**. Under Part 67, regulation 67.00.6(3), a Class 2 certificate is valid for:"},{t:"ul",items:["60 months, if the holder is less than 40 years of age","24 months, once the holder has passed their 40th birthday","12 months, once the holder has passed their 50th birthday"]},{t:"p",x:"Older SACAA FAQ pages show shorter Class 2 periods. This practice follows the regulation. Medical conditions can mean a shorter period, so the date on your certificate is the one that counts. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) explains how the date is counted and has a small expiry calculator."},{t:"h2",x:"How do I book with a designated examiner?",id:"examiner"},{t:"p",x:"A Class 2 renewal must be done by a Designated Aviation Medical Examiner (DAME). SACAA designates two kinds. Regular DAMEs may examine for and issue Class II and Class IV certificates. Senior DAMEs may also do Class I and Class III. Your family GP cannot issue a Class 2 certificate unless he or she is designated. Our guide to [SACAA medical examiners](/blog/sacaa-medical-examiners-dame/) shows how to check an examiner on the SACAA list."},{t:"p",x:"SACAA publishes the lists of Regular and Senior DAMEs on its aviation medicine page. It is worth checking that your examiner is on the current list."},{t:"p",x:"Dr A.O. Ndhlovu is listed by SACAA as a Regular DAME, number MR 336, at Grand Central Airport, Gate 2, Midrand. Class 2 renewals are within his scope. ClinoTrend does not currently issue Class 1."},{t:"h3",x:"When to book"},{t:"p",x:"Book a few weeks before your expiry date. That leaves time to get a specialist letter or an extra test if the examiner asks for one, without being grounded while you wait. Keep in mind that the new certificate runs from the month it is issued, so renewing many months early does not add the unused time to the new certificate."},{t:"h2",x:"What should I bring?",id:"documents"},{t:"p",x:"Regulation 67.00.7 says that when you attend the examination you must show proof of identity, show your licence and your latest medical certificate if you hold one, give the examiner information about your medical history, and sign a declaration that the information on the examination form is accurate, complete and true. In practice, bring:"},{t:"ul",items:["Your South African ID, driving licence or passport","Your pilot licence and your current medical certificate","Your logbook","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"]},{t:"p",x:"Complete the SACAA application form for a medical certificate online before you arrive. It is emailed only to the practice. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"h2",x:"What happens at the examination?",id:"examination"},{t:"p",x:"The examiner takes your medical history and examines you. At ClinoTrend a resting ECG, vision testing, a hearing test (audiometry) and urine screening are done on site. The examiner will tell you which other tests apply, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. Ask the practice how long to allow when you book."},{t:"p",x:"Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book."},{t:"h2",x:"When do I receive my certificate?",id:"certificate"},{t:"p",x:"If you meet the standards and no further reports are needed, the certificate can be issued at the end of the examination. SACAA procedure AM007 describes two copies with the same serial number: the yellow copy goes to the SACAA licensing department and you keep the white copy with you while flying. Medical restrictions, if any apply, are written on the certificate."},{t:"p",x:"If more information is needed, your assessment is deferred until it arrives. Complicated cases are referred to the SACAA Aeromedical Committee, which AM007 says meets on the third Tuesday of each month, with documents due seven days before the meeting. If you disagree with a decision, Part 67 allows an appeal to the Director of Civil Aviation within 30 days. Read [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/) for the full process."},{t:"h2",x:"What if I am running out of time?",id:"extension"},{t:"p",x:"Part 67, regulation 67.00.6(6), says you must apply for an extension **at least 15 days before your certificate expires**, and that the Director may extend it, on conditions, for **no more than 30 days**. SACAA procedure AM007 also says you must contact the SACAA medical department before the certificate expires, and SACAA's FAQ page explains where to send the request. An extension is a safety net, not a plan, so book your renewal early."},{t:"h2",x:"Where can I renew at Grand Central Airport?",id:"midrand"},{t:"p",x:"ClinoTrend Health & Aviation is at Gate 2, Office TG6B, Grand Central Airport, Midrand. [Book a Class 2 or Class 4 renewal](/book/?service=renewal), or read more on the [aviation medicals page](/aviation-medicals/) and the [Midrand aviation medical guide](/blog/aviation-medical-midrand-johannesburg/)."},{t:"cta",x:"Book your Class 2 renewal"}],faq:[{q:"Can my GP renew my Class 2 medical?",a:"Only if your GP is a SACAA Designated Aviation Medical Examiner. A Class 2 certificate must be issued by a DAME. Regular DAMEs issue Class 2 and Class 4. Senior DAMEs also issue Class 1 and Class 3."},{q:"How early can I renew my Class 2 medical?",a:"You can renew before the expiry date, but the new certificate runs from the month it is issued. Unused time on the old certificate is not added. Booking a few weeks early leaves room if a further report is needed."},{q:"What if my Class 2 medical expires before I can be examined?",a:"Contact the SACAA medical department before the expiry date to ask for an extension, as SACAA procedure AM007 requires. Regulation 67.00.6(6) says to apply at least 15 days before expiry, and an extension is for no more than 30 days. Then book your examination as soon as you can."},{q:"Do I need a chest X-ray for a Class 2 renewal?",a:"SACAA lists a chest X-ray at the initial examination and afterwards only when it is indicated on clinical grounds. The examiner will tell you which tests apply, including whether a chest X-ray is needed and whether it is done on site or referred."},{q:"Does a Class 1 medical cover Class 2 privileges?",a:"Yes. Regulation 67.00.2 says that a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates. ClinoTrend does not currently issue Class 1."}],sources:[e.validityReg,e.protocols,e.classes,e.application,e.am007,e.avmed,e.register,e.form,e.faq]},t={slug:"cabin-crew-medical-class-4-south-africa",title:"Cabin Crew Medical Requirements in SA | ClinoTrend",h1:"Cabin crew medical requirements in South Africa",description:"What medical cabin crew need in South Africa, who can examine you, Class 2 or Class 4, what to bring, and how to book at Grand Central Airport, Midrand.",excerpt:"What medical class cabin crew need, who can examine you, how long a certificate lasts, what to bring, and how to book at Grand Central Airport, Midrand.",keyword:"cabin crew medical south africa",question:"What medical do cabin crew need in South Africa?",answer:"Cabin crew need a Part 67 medical. The amended regulations list cabin crew under Class 4, while some SACAA pages still list Class 2. ClinoTrend can issue Class 2 or Class 4 for cabin crew, depending on what the airline or operator asks for. Tell us which class is required when you book.",facts:["Amended Part 67, regulation 67.00.2, lists the cabin crew member licence under Class 4.","Some SACAA pages, including the aviation medicine page and a medical-requirements table in the frequently asked questions, still list Class 2 or Class II for cabin crew.","Class 4 holders must also submit a yearly medical declaration to SACAA, on the form prescribed in SA-CATS 67 (regulation 67.00.9(3))."],secondary:["cabin crew class 4 medical","cabin crew medical certificate sacaa","class 4 aviation medical"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Cabin crew",body:[{t:"p",x:"If you are starting a cabin crew course, joining an airline, or renewing an existing cabin crew medical, you need a current medical certificate under Part 67 of the Civil Aviation Regulations. Official sources do not all use the same class name, so it helps to know what your airline or operator has asked for before you book."},{t:"h2",x:"Which medical class do cabin crew need?",id:"class"},{t:"p",x:"The amended Part 67 regulation 67.00.2 lists the **cabin crew member licence under Class 4**, alongside recreational licences such as microlight, gyroplane and glider. A SACAA frequently asked questions item says the regulation was promulgated in May 2019 and that cabin crew require a Class 4 medical."},{t:"p",x:"Some SACAA pages still list cabin crew under **Class 2 or Class II**, including the aviation medicine page and the medical-requirements table in the frequently asked questions. Because those pages have not all been updated to match the amended regulation, tell us which class your airline or operator has asked for when you book."},{t:"p",x:"Dr A.O. Ndhlovu at ClinoTrend is a Regular DAME (SACAA MR 336). He can issue **Class 2 or Class 4** for cabin crew, depending on what is required. Our guide to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) sets out who needs which class."},{t:"h2",x:"Who can do a cabin crew medical?",id:"who"},{t:"p",x:"If a Class 4 medical is required, it is the one class that does not have to be done by a designated examiner. Regulation 67.00.5 allows any medical practitioner registered with the HPCSA to perform the examination, provided the application, supporting reports and test results are sent to the designated body within 60 days for verification before the certificate is issued."},{t:"p",x:"A SACAA Designated Aviation Medical Examiner (DAME) can also examine you and issue a Class 4 certificate. Regular and Senior DAMEs are both authorised for Class IV. A Class 2 medical, if that is what is required, must be done by a DAME. Dr Ndhlovu can do either class at Grand Central Airport in Midrand."},{t:"h2",x:"What does the cabin crew medical include?",id:"tests"},{t:"p",x:"The examiner takes your medical history and examines you. Typical parts of the examination include:"},{t:"ul",items:["Your medical history, taken on the SACAA form CA 67-02(a), and a signed declaration","A physical examination","Vision testing","A hearing test (audiometry)","A resting ECG","Urine screening"]},{t:"p",x:"At ClinoTrend the ECG, vision testing, hearing test and urine screening are done on site. The examiner will tell you which other tests apply, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. Height and swimming tests, if an airline requires them for training or employment, are not part of the SACAA medical itself."},{t:"h2",x:"How long does a cabin crew medical last?",id:"validity"},{t:"p",x:"If you are issued a **Class 4** certificate, regulation 67.00.6(4) sets the period at 60 months if you are less than 40 years of age, and 36 months if you are 40 or older, calculated to the last day of a month. If you are issued a **Class 2** certificate, regulation 67.00.6(3) sets 60 months if you are less than 40, 24 months after your 40th birthday, and 12 months after your 50th birthday. Medical conditions can mean a shorter period. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) includes a calculator for both classes."},{t:"h3",x:"The yearly Class 4 declaration"},{t:"p",x:"If you hold a Class 4 certificate, regulation 67.00.9(3) requires you to complete and submit a medical declaration to SACAA **every year**, on the form prescribed in SA-CATS 67. Contact the practice or SACAA if you are unsure which form to use."},{t:"h2",x:"Should I get the medical before a cabin crew course?",id:"course"},{t:"p",x:"Yes, if the school or airline asks you to hold a current medical before you start, or before you fly as part of training. Completing it early means a finding that needs a further report will not delay the start of your course. Ask the school which class it wants you to book."},{t:"h2",x:"What should cabin crew bring?",id:"bring"},{t:"p",x:"Regulation 67.00.7 requires you to show proof of identity, your licence and your latest medical certificate if you have one, give your medical history and sign a declaration. Bring:"},{t:"ul",items:["Your South African ID or passport","Your cabin crew licence, if you already hold one, and your current medical certificate","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"]},{t:"p",x:"Complete the SACAA application form for a medical certificate online before you arrive. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"h2",x:"How do I book a cabin crew medical in Midrand?",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, between Johannesburg and Pretoria. You can reach the airport from Midrand Gautrain Station by e-hailing or taxi; contact the practice for directions. Ask the practice how long to allow when you book. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book."},{t:"p",x:"[Book a Class 4 medical](/book/?service=class-4) or a [Class 2 medical](/book/?service=class-2), or read more on the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book your cabin crew medical"}],faq:[{q:"Do cabin crew need a Class 2 or a Class 4 medical?",a:"It depends on what the airline or operator asks for. Amended Part 67 lists cabin crew under Class 4. Some SACAA pages still list Class 2 or Class II. ClinoTrend can issue Class 2 or Class 4 for cabin crew. Tell us which class is required when you book."},{q:"Can my own GP do my cabin crew medical?",a:"If a Class 4 medical is required, regulation 67.00.5 allows a medical practitioner registered with the HPCSA to perform the examination, provided the results are sent for verification within 60 days. A Class 2 medical must be done by a designated aviation medical examiner. A DAME can also issue Class 4."},{q:"How long is a Class 4 medical valid for cabin crew?",a:"Under regulation 67.00.6(4), a Class 4 certificate is valid for 60 months if you are less than 40 years of age, and 36 months if you are 40 or older, to the last day of a month. If you are issued a Class 2 certificate instead, different periods apply under regulation 67.00.6(3)."},{q:"Do I need the medical before my cabin crew course?",a:"If the school or airline requires a current medical before you start, or before you fly in training, complete it first. Ask which class they want you to book."},{q:"Are height and swimming part of the medical?",a:"No. Height and swimming requirements, if an airline or school uses them, are training or employment conditions, not part of the SACAA medical examination itself."}],sources:[e.cabin,e.classes,e.faq,e.class4,e.duties,e.validityReg,e.protocols,e.avmed,e.register,e.form]},o={slug:"aviation-medical-midrand-johannesburg",title:"Aviation Medical Examiner, Johannesburg | ClinoTrend",h1:"Aviation medical examiner in Midrand and Johannesburg",description:"Find a SACAA aviation medical examiner in Midrand and Johannesburg: what to bring, how the exam works, fees from R1,500, and how to book at Grand Central.",excerpt:"Where to find a SACAA designated examiner in Midrand, what to bring, how the examination works, fees, and how to book at Grand Central Airport.",keyword:"aviation medical examiner johannesburg",question:"Where can I get an aviation medical near Johannesburg?",answer:"Dr A.O. Ndhlovu, a SACAA Regular Designated Aviation Medical Examiner (MR 336), does Class 2 and Class 4 aviation medicals at ClinoTrend, Gate 2, Grand Central Airport in Midrand, on the N1 between Johannesburg and Pretoria. Book online, or fly in to FAGC. ClinoTrend does not currently issue Class 1 or Class 3.",facts:["Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book.","On-site tests include a resting ECG, vision testing, audiometry (hearing) and urine screening.","You can reach Grand Central from Midrand Gautrain Station by e-hailing or taxi. Contact the practice for directions."],secondary:["aviation medical midrand","sacaa medical examiner johannesburg","class 2 medical midrand"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Midrand",body:[{t:"p",x:"If you are looking for a SACAA aviation medical examiner in Midrand or Johannesburg, ClinoTrend Health & Aviation is at Grand Central Airport, between Johannesburg and Pretoria. Dr A.O. Ndhlovu is listed on the SACAA list of Regular Designated Aviation Medical Examiners as MR 336."},{t:"h2",x:"Which medicals are done at Grand Central?",id:"which"},{t:"p",x:"As a Regular DAME, Dr Ndhlovu issues Class 2 and Class 4 medical certificates. That covers student and private pilots, recreational pilots, and cabin crew (Class 2 or Class 4, depending on what the airline or operator asks for). Our guides to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) and [cabin crew medical requirements](/blog/cabin-crew-medical-class-4-south-africa/) explain who needs which class."},{t:"table",caption:"Medical classes at ClinoTrend (Grand Central Airport, Midrand)",head:["Class","Typical licences","Issued here?"],rows:[["Class 2","Student pilots (SPL) and private pilots (PPL), plus other licences listed in regulation 67.00.2","Yes"],["Class 4","Recreational pilots, and cabin crew when a Class 4 is required","Yes"],["Class 1","Commercial and airline transport pilots","Not currently"],["Class 3","Air traffic controllers","Not currently"]]},{t:"p",x:"Class 1 and Class 3 medicals need a SACAA Senior DAME. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"h2",x:"Where is the practice?",id:"where"},{t:"p",x:"ClinoTrend is in the Main Terminal Building, Gate 2, Office TG6B, Grand Central Airport, 3 New Road, Midrand. You can drive in, or fly in to FAGC and park on the apron outside the Gate 2 terminal doors."},{t:"ul",items:["**By car:** Grand Central Airport is on the N1 between Johannesburg and Pretoria. Use Gate 2.","**By Gautrain:** You can reach Grand Central from Midrand Gautrain Station by e-hailing or taxi. Contact the practice for directions.","**By air:** Fly in to Grand Central (FAGC) and park on the apron outside the terminal doors."]},{t:"p",x:"The [contact page](/contact/) has hours, a map and further directions."},{t:"h2",x:"What should I bring?",id:"bring"},{t:"p",x:"Part 67 (regulation 67.00.7) requires you to show proof of identity, your licence and your latest medical certificate if you have one, give your medical history and sign a declaration. Bring:"},{t:"ul",items:["Your South African ID or passport","Any aviation licence you hold, and your logbook if you are renewing","Your most recent aviation medical certificate, if you have one","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"]},{t:"p",x:"Complete the SACAA application form for a medical certificate online before you arrive. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"h2",x:"What happens during the examination?",id:"examination"},{t:"p",x:"The examiner takes your history and examines you. At ClinoTrend a resting ECG, vision testing, a hearing test (audiometry) and urine screening are done on site. The examiner will tell you which other tests apply, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. Ask the practice how long to allow when you book, and whether you should arrive early to complete paperwork."},{t:"h2",x:"What does an aviation medical cost?",id:"fees"},{t:"p",x:"Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book. Fees differ between examiners and are set by each practice."},{t:"h2",x:"How do I book?",id:"book"},{t:"p",x:"Medicals are by appointment only. [Book an appointment](/book/), choose a [Class 2 medical](/book/?service=class-2), a [Class 4 medical](/book/?service=class-4), or a [renewal](/book/?service=renewal), or read the [aviation medicals page](/aviation-medicals/). Flight schools, academies and airlines can arrange group bookings in advance."},{t:"cta",x:"Book your aviation medical in Midrand"}],faq:[{q:"Where can I get an aviation medical near Johannesburg?",a:"At ClinoTrend Health & Aviation, Gate 2, Grand Central Airport, Midrand, with Dr A.O. Ndhlovu, a SACAA Regular Designated Aviation Medical Examiner (MR 336). The practice does Class 2 and Class 4 medicals."},{q:"How long does an aviation medical take?",a:"Ask the practice how long to allow when you book, and arrive a little early. Bringing the documents on the checklist and completing the SACAA form online beforehand helps the visit run smoothly."},{q:"How much does an aviation medical cost in Midrand?",a:"Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book."},{q:"Can I do a Class 1 medical at ClinoTrend?",a:"ClinoTrend does not currently issue Class 1. Class 1 and Class 3 medicals need a SACAA Senior DAME."},{q:"Can I fly in to Grand Central for my medical?",a:"Yes. Fly in to Grand Central Airport (FAGC) and park on the apron outside the Gate 2 terminal doors. Book first, as medicals are by appointment only."}],sources:[e.register,e.avmed,e.classes,e.application,e.form,e.faq]},s={slug:"class-2-medical-validity-by-age",title:"How Long a Class 2 Medical Is Valid | ClinoTrend",h1:"How long a Class 2 medical is valid, by age",description:"How long a SACAA Class 2 medical is valid: 60 months under 40, 24 months from 40, 12 months from 50, under Part 67. Includes Class 4 periods and a calculator.",excerpt:"Class 2 validity under Part 67: 60 months under 40, 24 months after 40, 12 months after 50. Class 4 periods, how the date is counted, and a calculator.",keyword:"class 2 medical validity",question:"How long is a SACAA Class 2 medical valid?",answer:"Under Part 67, regulation 67.00.6(3), a Class 2 medical is valid for 60 months if you are less than 40, 24 months after your 40th birthday, and 12 months after your 50th birthday, running to the last day of a month. Older FAQ pages show shorter periods; this practice follows the regulation. The date on your certificate counts.",facts:["A Class 4 certificate is valid for 60 months if you are less than 40, and 36 months from age 40, under regulation 67.00.6(4).","A DAME or a SACAA medical assessor may shorten the period and endorse a limitation, under regulation 67.00.6(5).","Unused time is not carried over when you renew: the new certificate runs from the month it is issued."],secondary:["class 2 medical certificate validity south africa","class 4 medical validity","sacaa medical expiry"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Validity",body:[{t:"p",x:"The date on your medical certificate is the date that matters. The periods below come from Part 67, regulation 67.00.6, and from the SACAA summarised medical protocols (effective 16 November 2021). Older SACAA FAQ pages show shorter Class 2 periods. This practice follows the regulation."},{t:"h2",x:"How long is a Class 2 medical valid?",id:"class-2"},{t:"p",x:"Regulation 67.00.6(3) says a Class 2 certificate is valid for:"},{t:"ul",items:["60 months, if the holder is less than 40 years of age","24 months, once the holder has passed their 40th birthday","12 months, once the holder has passed their 50th birthday"]},{t:"p",x:"The period is calculated from the last day of the calendar month in which the certificate is issued. For example, a Class 2 issued on 10 March 2026 to a holder younger than 40 expires on 31 March 2031. The same issue date expires on 31 March 2028 after the 40th birthday, and on 31 March 2027 after the 50th birthday."},{t:"h2",x:"How is the expiry date counted?",id:"counted"},{t:"p",x:"Validity always runs to the last day of a month. If a certificate is issued part way through a month, that whole month is counted, and the period then runs in calendar months from the end of that month. Medical conditions can mean more frequent examinations, so always use the date printed on your certificate."},{t:"calc"},{t:"h2",x:"How long is a Class 4 medical valid?",id:"class-4"},{t:"p",x:"Regulation 67.00.6(4) says a Class 4 certificate is issued for a period not exceeding 60 calendar months if the applicant is less than 40 years of age, and 36 calendar months if the applicant is 40 years of age or more, again to the last day of the month. Cabin crew may be issued Class 2 or Class 4; use the periods that match the class on your certificate. See [cabin crew medical requirements](/blog/cabin-crew-medical-class-4-south-africa/)."},{t:"h2",x:"What about Class 1 and Class 3?",id:"other-classes"},{t:"p",x:"Class 1 periods are set out in regulation 67.00.6(1). In short, a Class 1 certificate is issued for 12 months if the applicant is less than 40. From age 40 the period depends on the licence and the type of operation: six months for an airline transport pilot in single-crew commercial air transport operations; 12 months for an airline transport pilot in multi-crew operations, and for a commercial pilot, until age 60; and six months from age 60 for those last two groups. Holders in the 12 month bands from age 40 may also have extra reporting duties under regulation 67.00.6(2)."},{t:"p",x:"Class 3, under regulation 67.00.6(3), is 48 months if the holder is less than 40, 24 months after the 40th birthday, and 12 months after the 50th birthday. Class 1 and Class 3 medicals need a SACAA Senior DAME. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"h2",x:"Can the period be shorter?",id:"shorter"},{t:"p",x:"Yes. Regulation 67.00.6(5) allows a DAME or a medical assessor to reduce the period of validity and endorse the reason, or any limitation, if a further examination or test is needed, or if safe performance of the holder's duties depends on a shorter period or a special limitation."},{t:"h2",x:"What changes when I turn 40 or 50?",id:"birthdays"},{t:"p",x:"The Class 2 period is set by your age on the date the certificate is issued. Once you have passed your 40th birthday, a new Class 2 is issued for 24 months. Once you have passed your 50th birthday, a new Class 2 is issued for 12 months. Turning 40 or 50 during a current period does not cut that certificate short; the shorter period applies at the next issue."},{t:"h2",x:"How should I plan renewals?",id:"planning"},{t:"p",x:"Book a few weeks before the expiry date, so there is time if the examiner asks for a specialist letter or an extra test. Renewing many months early does not add the unused time to the new certificate, because the new period starts from the month of issue. Our [Class 2 renewal guide](/blog/renew-sacaa-class-2-medical/) walks through the steps."},{t:"h2",x:"What if I am close to expiry?",id:"expiry"},{t:"p",x:"Regulation 67.00.6(6) says you must apply for an extension at least 15 days before your certificate expires. The Director may extend it, on conditions, for no more than 30 days. SACAA procedure AM007 also says you must contact the SACAA medical department before the certificate expires. An extension is a safety net, not a plan."},{t:"cta",x:"Book your Class 2 or Class 4 renewal"}],faq:[{q:"How long is a Class 2 medical valid if I am under 40?",a:"60 months, calculated from the last day of the month in which the certificate is issued, under regulation 67.00.6(3). Medical conditions can mean a shorter period. The date on your certificate is the one that applies."},{q:"How long is a Class 2 medical valid after 40?",a:"24 months once you have passed your 40th birthday, and 12 months once you have passed your 50th birthday, under regulation 67.00.6(3). Older SACAA FAQ pages show shorter periods; this practice follows the regulation."},{q:"How long is a Class 4 medical valid?",a:"60 months if you are less than 40 years of age, and 36 months if you are 40 or older, under regulation 67.00.6(4), to the last day of a month."},{q:"Can my certificate be valid for a shorter time?",a:"Yes. Regulation 67.00.6(5) allows a DAME or a medical assessor to reduce the period and endorse a reason or a limitation when a further test is needed, or when safety depends on it."},{q:"Can I extend my medical certificate?",a:"Yes, by applying to SACAA at least 15 days before expiry. Regulation 67.00.6(6) allows an extension of no more than 30 days, on conditions. Contact the SACAA medical department before the certificate expires."}],sources:[e.validityReg,e.protocols,e.am007,e.classes,e.faq,e.avmed]},n={slug:"sacaa-medical-classes-explained",title:"Aviation Medical Classes in South Africa | ClinoTrend",h1:"SACAA aviation medical classes explained",description:"Which SACAA medical class you need: Class 1, 2, 3, 4 and 5 under Part 67, who may examine you, and which classes ClinoTrend issues in Midrand.",excerpt:"Class 1 to Class 5 under Part 67: which licences they cover, who may examine you, and which classes are issued at ClinoTrend in Midrand.",keyword:"sacaa medical classes",question:"Which SACAA medical class do I need?",answer:"It depends on your licence. Under Part 67, regulation 67.00.2, commercial and airline pilots need Class 1, student and private pilots Class 2, air traffic services staff Class 3, most recreational pilots Class 4, and paragliding, hang gliding and parachute licences a Class 5 declaration. ClinoTrend issues Class 2 and Class 4.",facts:["A flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates (regulation 67.00.2(2)).","Regular DAMEs issue Class II and Class IV. Senior DAMEs also issue Class I and Class III, as described on the SACAA aviation medicine page.","ClinoTrend does not currently issue Class 1 or Class 3."],secondary:["class 1 medical south africa","class 2 vs class 4 medical","class 5 medical sacaa"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Classes",body:[{t:"p",x:"South African aviation licences are tied to a class of medical certificate under Part 67 of the Civil Aviation Regulations. The class you need is set by your licence, not by a preference. This guide follows regulation 67.00.2 for which licences sit under each class, and official SACAA wording for who may examine you."},{t:"h2",x:"What are the five SACAA medical classes?",id:"five"},{t:"table",caption:"SACAA medical classes (Part 67, regulation 67.00.2, as amended)",head:["Class","Main licences it covers","Who examines"],rows:[["Class 1","Airline transport pilot (ATPL), commercial pilot (CPL) for aeroplane, airship and helicopter, instrument rating, Class I test pilot rating","Senior DAME"],["Class 2","Student pilot (SPL), private pilot (PPL) for aeroplane, airship and helicopter, flight engineer, free balloon CPL, commercial glider pilot","Regular or Senior DAME"],["Class 3","Air traffic controller (ATC), air traffic service assistant, remote pilot (RPL)","Senior DAME"],["Class 4","Cabin crew member licence, and recreational licences such as microlight, gyroplane, glider and free balloon","Regular or Senior DAME, or a registered medical practitioner under regulation 67.00.5"],["Class 5","Paraglider, hang glider, powered paratrike and parachute licences and their student licences","Registered medical practitioner (declaration sent to SACAA)"]]},{t:"p",x:'The table shortens the lists. The full wording is in the [SACAA copy of regulation 67.00.2](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-general-information/Ammended%20%20Part%2067%20Regulations%20Classes%20of%20medical%20certificates.pdf), which also lists instructor ratings, tandem licences and test pilot ratings. The "Who examines" column follows the SACAA aviation medicine page (Regular DAME: Class II and IV; Senior DAME: Class I to IV), together with regulation 67.00.5 for Class 4 and regulation 67.00.2(8) and (9) for Class 5.'},{t:"h2",x:"What is the difference between a Class 1 and a Class 2 medical?",id:"class1-class2"},{t:"p",x:"A Class 1 is for flying as a profession: the CPL, the ATPL and the instrument rating. A Class 2 is for the student and private pilot licences, among others. Class 1 examinations must be done by a SACAA **Senior** Designated Aviation Medical Examiner (DAME). Validity periods also differ; see [how long a Class 2 medical is valid](/blog/class-2-medical-validity-by-age/), which also summarises Class 1 periods under regulation 67.00.6(1)."},{t:"p",x:"Regulation 67.00.2(2) adds a useful rule: a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates. If you stop flying commercially, regulation 67.00.2(4) lets you ask for an expired Class 1 to be substituted by a Class 2 or Class 4, with the remaining validity worked out under regulation 67.00.6. ClinoTrend does not currently issue Class 1."},{t:"h2",x:"Which class do cabin crew need?",id:"cabin"},{t:"p",x:"Amended regulation 67.00.2 lists the cabin crew member licence under **Class 4**. Some SACAA pages, including the aviation medicine page and a medical-requirements table in the frequently asked questions, still list cabin crew under Class 2 or Class II. ClinoTrend can issue Class 2 or Class 4 for cabin crew, depending on what the airline or operator asks for. Tell us which class is required when you book. The [cabin crew medical guide](/blog/cabin-crew-medical-class-4-south-africa/) explains this in more detail."},{t:"h2",x:"Which class do recreational pilots need?",id:"recreational"},{t:"p",x:"Most recreational licences, including microlight, gyroplane, glider, light sport aeroplane and free balloon, sit under **Class 4**. Paragliding, hang gliding, powered paratrike and parachute licences, and their student licences, sit under **Class 5**."},{t:"h2",x:"What is a Class 5 medical?",id:"class5"},{t:"p",x:"Class 5 is a declaration sent to SACAA, signed by a registered medical practitioner. Under regulation 67.00.2(8), a person under 60 years of age who submits a duly completed Class 5 medical self-declaration, on the prescribed form and signed by a medical practitioner registered under the Health Professions Act, is deemed to hold a Class 5 medical certificate. Under regulation 67.00.2(9), from age 60 the form is the medical declaration prescribed for that age, also signed by a registered medical practitioner."},{t:"h2",x:"Who can examine you for each class?",id:"who"},{t:"p",x:"SACAA's aviation medicine page states that Regular DAMEs may do Class II and Class IV, and Senior DAMEs may do Class I, II, III and IV. Class 4 may also be done by a registered medical practitioner under regulation 67.00.5, subject to verification. Class 5 is the declaration described above, signed by a registered medical practitioner. Our guide to [checking a SACAA medical examiner](/blog/sacaa-medical-examiners-dame/) shows how to use the official lists. Dr A.O. Ndhlovu is a Regular DAME (MR 336) and issues Class 2 and Class 4 at Grand Central Airport, Midrand. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"h2",x:"How long is each certificate valid?",id:"validity"},{t:"p",x:"Validity periods are set in regulation 67.00.6 and depend on the class and your age. This page does not repeat every figure. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) sets out Class 2 and Class 4, summarises Class 1 and Class 3, and includes a calculator. A DAME or a medical assessor may also shorten the period under regulation 67.00.6(5)."},{t:"h2",x:"Not sure which class you need?",id:"book"},{t:"p",x:"Check the licence you hold or are training for against regulation 67.00.2, or ask your flight school or operator. Then [book the matching medical](/book/), or start from the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book a Class 2 or Class 4 medical"}],faq:[{q:"Do private pilots need a Class 1 or a Class 2 medical?",a:"A Class 2. Regulation 67.00.2 lists the student pilot licence and the private pilot licence for aeroplane, airship and helicopter under Class 2."},{q:"Does a Class 1 medical cover Class 2?",a:"Yes. Regulation 67.00.2(2) says a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates."},{q:"Which medical class do air traffic controllers need?",a:"Class 3. It also covers air traffic service assistants and remote pilots (RPL). Class 3 medicals are done by a SACAA Senior DAME."},{q:"Can a Regular DAME do a Class 1 medical?",a:"No. A Regular DAME does Class II and Class IV. Class I and Class III need a Senior DAME. ClinoTrend does not currently issue Class 1 or Class 3."},{q:"What is a Class 5 medical?",a:"A declaration sent to SACAA, signed by a registered medical practitioner, for paragliding, hang gliding, powered paratrike and parachute licences. For applicants under 60 the prescribed form is the Class 5 medical self-declaration. From age 60 the form is the medical declaration prescribed for that age."}],sources:[e.classes,e.classesReg,e.class4,e.validityReg,e.avmed,e.register]},r={slug:"student-pilot-medical-south-africa",title:"Student Pilot Medical Requirements | ClinoTrend",h1:"Student pilot medical requirements in South Africa",description:"What medical a student pilot needs in South Africa before flying solo, when to book, what to bring, and how schools can arrange group medicals in Midrand.",excerpt:"The medical a student pilot needs before flying solo, when to book, what to bring, and how flight schools can arrange group medicals in Midrand.",keyword:"student pilot medical south africa",question:"What medical does a student pilot need in South Africa?",answer:"Before you fly solo on a student pilot licence you need a valid medical certificate issued under Part 67. An SPL for aeroplane, airship or helicopter sits under Class 2. Recreational student licences sit under Class 4. Book a few weeks before you expect to fly solo, and complete the SACAA application form beforehand.",facts:["Part 61, regulation 61.02.1, says an applicant for an SPL or ISPL must be 15 years or older, hold a valid medical certificate issued under Part 67, and be registered with an approved training organisation.","Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book.","Flight schools can arrange group medicals at ClinoTrend in advance."],secondary:["student pilot licence medical","first class 2 medical","flight school aviation medical"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Student pilots",body:[{t:"p",x:"A first aviation medical is one of the early steps in learning to fly. This guide covers what a student pilot needs, when to book, what happens at a first Class 2 medical, and how flight schools can book a group at Grand Central Airport, Midrand."},{t:"h2",x:"Do student pilots need a medical?",id:"need"},{t:"p",x:"Yes. Part 61, regulation 61.02.1 (as amended on 21 August 2026), says an applicant for a student pilot licence (SPL) or integrated student pilot licence (ISPL) must be 15 years or older, hold a valid medical certificate issued in terms of Part 67, and be registered with an approved training organisation (ATO). Your SPL is what allows you to fly solo under instruction, so the medical comes first."},{t:"h2",x:"Which medical class does a student pilot need?",id:"class"},{t:"p",x:"Regulation 67.00.2 lists the SPL under **Class 2**, alongside the private pilot licence (PPL). Students on recreational licences are different: an SPL for a microlight, gyroplane, light sport aeroplane or glider licence sits under **Class 4**. Our guide to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) has the full list."},{t:"p",x:"The 21 August 2026 amendment added the integrated student pilot licence (ISPL). An ISPL, like an SPL, requires a valid medical certificate issued under Part 67. Confirm with your flight school, or contact the practice, which class is required for your course."},{t:"p",x:"A commercial pilot licence (CPL), an airline transport pilot licence (ATPL) and an instrument rating all need a **Class 1** medical, which only a SACAA Senior DAME may do. Ask your flight school when it wants you to hold a Class 1. Dr Ndhlovu is a Regular DAME, so at ClinoTrend we do the Class 2 that covers your SPL and PPL. ClinoTrend does not currently issue Class 1."},{t:"h2",x:"When should I book my first medical?",id:"when"},{t:"p",x:"Book a few weeks before you expect to fly solo, so there is time if the examiner asks for a further test or a report. You do not usually need the certificate before your first dual lessons, unless your school asks for it. Complete the SACAA application form online before you arrive."},{t:"h2",x:"What happens at a first Class 2 medical?",id:"first"},{t:"p",x:"You complete your medical history on the SACAA form and sign a declaration that it is accurate, complete and true, as regulation 67.00.7 requires. The doctor then examines you. At ClinoTrend these tests are done on site:"},{t:"ul",items:["A resting ECG","Vision testing","A hearing test (audiometry)","Urine screening"]},{t:"p",x:"The examiner will tell you which other tests apply for a first Class 2, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. SACAA's medical requirements list a chest X-ray at the initial examination, and afterwards only when it is indicated on clinical grounds. Ask the practice how long to allow when you book."},{t:"h2",x:"How long is a student pilot medical valid?",id:"validity"},{t:"p",x:"If you are issued a Class 2 certificate and you are less than 40 years of age, regulation 67.00.6(3) sets the period at 60 months, to the last day of the month of issue. After 40 and after 50 the period is shorter. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) explains the dates and has a calculator. Recreational students issued a Class 4 follow the Class 4 periods."},{t:"h2",x:"What should a student pilot bring?",id:"bring"},{t:"p",x:"Bring your South African ID or passport, a list of every medicine you take, glasses or contact lenses if you use them, and any reports from your own doctor if you have a medical condition. Complete the SACAA application form beforehand. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"p",x:"Students can start from 15. If you are under 18, contact the practice to confirm any extra requirements before you book."},{t:"h2",x:"Can flight schools book group medicals?",id:"groups"},{t:"p",x:"Yes. Flight schools can arrange group medicals at ClinoTrend in advance. Call or email the practice with the number of students and the dates that suit you. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book. [Book a Class 2 medical](/book/?service=class-2), or read the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book a student pilot medical"}],faq:[{q:"Do I need a medical before my first flying lesson?",a:"You need a valid medical certificate issued under Part 67 before you fly solo on a student pilot licence. Some schools also ask for it earlier. Check with your flight school."},{q:"What medical class is a student pilot licence?",a:"An SPL for aeroplane, airship or helicopter is listed under Class 2 in regulation 67.00.2. Recreational student licences such as microlight or glider sit under Class 4."},{q:"How old must I be for a student pilot licence?",a:"Regulation 61.02.1, as amended on 21 August 2026, says an applicant for an SPL or ISPL must be 15 years or older. If you are under 18, contact the practice to confirm any extra requirements before you book."},{q:"Can I do my Class 1 medical at ClinoTrend?",a:"ClinoTrend does not currently issue Class 1. A Class 1 needs a SACAA Senior DAME. Dr Ndhlovu is a Regular DAME and does Class 2 and Class 4 medicals."},{q:"Can a flight school book medicals for a group of students?",a:"Yes. Group bookings are arranged in advance. Contact the practice with the number of students and the dates that suit you."}],sources:[e.spl,e.classes,e.application,e.validityReg,e.protocols,e.form,e.avmed,e.register]},l={slug:"sacaa-medical-examiners-dame",title:"SACAA Medical Examiners: How to Check | ClinoTrend",h1:"SACAA medical examiners: how to check a DAME",description:"What a SACAA Designated Aviation Medical Examiner (DAME) is, Regular versus Senior, how to check the official list, and where to find one in Midrand.",excerpt:"What a DAME is, the difference between Regular and Senior examiners, how to check the official SACAA lists, and where to find one in Midrand.",keyword:"sacaa medical examiners",question:"How do I check that an aviation medical examiner is designated by SACAA?",answer:"A DAME is a doctor designated by the Director of Civil Aviation to examine applicants and to issue or defer certificates under Part 67. Regular DAMEs do Class 2 and Class 4. Senior DAMEs also do Class 1 and Class 3. Check the SACAA lists. Dr A.O. Ndhlovu is listed as Regular DAME MR 336 at Grand Central Airport, Midrand.",facts:["SACAA publishes separate lists of Regular and Senior Designated Aviation Medical Examiners on its aviation medicine page.","Your family GP cannot issue a Class 1, 2 or 3 certificate unless he or she is designated. Class 4 may be done by a registered medical practitioner under regulation 67.00.5.","Always match the examiner's designation to the class you need."],secondary:["designated aviation medical examiner","dame sacaa","aviation medical examiner midrand"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Examiners",body:[{t:"p",x:"An aviation medical in South Africa has to be done by the right kind of examiner for the class you need. This guide explains what a Designated Aviation Medical Examiner is, how Regular and Senior designations differ, and how to check the official SACAA lists before you book."},{t:"h2",x:"What is a DAME?",id:"what"},{t:"p",x:"A Designated Aviation Medical Examiner, or DAME, is a doctor designated by the Director of Civil Aviation under Part 67, regulation 67.00.4, to do aviation medical examinations and to issue, or defer, medical certificates on behalf of SACAA. The designation is personal to that doctor and is shown by a designation number, such as MR 336."},{t:"h2",x:"What is the difference between a Regular DAME and a Senior DAME?",id:"difference"},{t:"p",x:"SACAA's aviation medicine page describes two categories:"},{t:"ul",items:["**Regular DAME:** authorised to examine for and issue Class II and Class IV medical certificates.","**Senior DAME:** authorised to examine for and issue Class I, II, III and IV medical certificates."]},{t:"p",x:"If you need a Class 1 or Class 3 medical, you must see a Senior DAME. A Regular DAME can renew a Class 2 or issue a Class 4. Our guide to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) lists which licences sit under each class."},{t:"h2",x:"How do I check that an examiner is designated?",id:"check"},{t:"p",x:"SACAA publishes the names of designated examiners on its [aviation medicine page](https://www.caa.co.za/industry-information/aviation-medicine/). There is a list of Regular DAMEs and a list of Senior DAMEs. Look for the doctor's name, designation number and the town or practice address, and check that the list is the current one."},{t:"p",x:"A current designation matters because only a designated examiner may issue the classes they are authorised for. If you are unsure, contact the SACAA medical department or ask the practice to confirm the designation number against the list."},{t:"h2",x:"Can my own GP do the medical?",id:"gp"},{t:"p",x:"Not for Class 1, 2 or 3, unless your GP is also a designated examiner. Class 4 is different: regulation 67.00.5 allows a medical practitioner registered with the HPCSA to perform the examination, provided the application and results are sent for verification within 60 days before the certificate is issued. A DAME can also issue Class 4."},{t:"h2",x:"Where can I find a SACAA medical examiner in Midrand?",id:"midrand"},{t:"p",x:"Dr A.O. Ndhlovu is listed as a Regular DAME, designation MR 336, at ClinoTrend Health & Aviation, Gate 2, Grand Central Airport, Midrand. He does Class 2 and Class 4 medicals, including for cabin crew when either class is required. ClinoTrend does not currently issue Class 1 or Class 3. [Book an appointment](/book/), or read the [Midrand aviation medical guide](/blog/aviation-medical-midrand-johannesburg/) and the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book with a designated examiner in Midrand"}],faq:[{q:"What does DAME stand for?",a:"Designated Aviation Medical Examiner. It is a doctor designated by the Director of Civil Aviation under Part 67 to examine applicants and to issue or defer medical certificates on behalf of SACAA."},{q:"Where is the list of SACAA medical examiners?",a:"On the SACAA aviation medicine page. SACAA publishes a list of Regular DAMEs and a list of Senior DAMEs. Check the current list for the doctor's name and designation number."},{q:"Can a Regular DAME renew my Class 2?",a:"Yes. Regular DAMEs are authorised for Class II and Class IV. Senior DAMEs may also do Class I and Class III."},{q:"Can my own GP do my aviation medical?",a:"Only if your GP is a designated examiner, except for Class 4, which regulation 67.00.5 allows a registered medical practitioner to perform, subject to verification. Class 1, 2 and 3 must be done by a DAME of the right category."},{q:"Is Dr Ndhlovu a SACAA designated examiner?",a:"Yes. He is listed on the SACAA list of Regular DAMEs as MR 336, at ClinoTrend, Grand Central Airport, Midrand. He does Class 2 and Class 4 medicals. ClinoTrend does not currently issue Class 1 or Class 3."}],sources:[e.register,e.avmed,e.designation,e.class4,e.am007,e.classes]},d={slug:"aviation-medical-deferred-what-next",title:"Aviation Medical Deferral: What Next | ClinoTrend",h1:"What happens if your aviation medical is deferred",description:"What happens if a SACAA aviation medical is deferred: next steps under Part 67, the Aeromedical Committee, limitations, the 30 day appeal, and what to report.",excerpt:"What a deferral means, how SACAA reviews a case, limitations and shorter validity, the 30 day appeal, and what you must report between medicals.",keyword:"aviation medical deferred",question:"What happens if my SACAA aviation medical is deferred?",answer:"A deferral is not a final no. Under Part 67 a designated examiner may defer your certificate until SACAA gives an instruction, usually after a further report or test. Complicated cases go to the SACAA Aeromedical Committee. A certificate can also be issued with a limitation or a shorter validity, and you may appeal a decision within 30 days.",facts:["Examination records may be used to issue a certificate for no more than 90 days (regulation 67.00.12). After that the examination may need to be repeated.","SACAA procedure AM007 says the Aeromedical Committee meets on the third Tuesday of each month, and documents must be submitted at least seven days before the meeting.","An appeal against a deferral or similar decision is 30 days; an appeal against a suspension is 14 days under regulation 67.00.14."],secondary:["sacaa aeromedical committee","medical certificate limitation","appeal aviation medical"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Deferrals",body:[{t:"p",x:"Most aviation medicals end with a certificate issued on the day. Sometimes the examiner cannot decide yet. This guide explains what a deferral means under Part 67, the official next steps, limitations, appeals, and what you must report between medicals."},{t:"h2",x:"What does a deferred medical mean?",id:"mean"},{t:"p",x:"Part 67, regulation 67.00.4, says a designated examiner may examine you, issue your certificate, or **defer** it pending an instruction from SACAA. A deferral means the examiner cannot decide on the day, usually because a finding or something in your history needs more information. It is not the same as being declared unfit."},{t:"h2",x:"What happens after a deferral?",id:"next"},{t:"ol",items:["The examiner will explain which reports or tests are needed, and how they are sent to SACAA.","You obtain those reports or tests and provide them as instructed.","Straightforward cases can then be finalised. SACAA procedure AM007 says complicated cases are referred to the SACAA **Aeromedical Committee (AMC)**, an advisory panel of medical and aviation industry experts."]},{t:"p",x:"Waiting times depend on the reports and on SACAA. The practice cannot give a typical wait. Time still matters: regulation 67.00.12 says the records of a medical examination may be used to issue a certificate for no more than **90 days**. If your reports take longer than that, the examination may have to be repeated."},{t:"h2",x:"Can I get a certificate with a limitation?",id:"limitation"},{t:"p",x:"Yes. Part 67 allows a certificate to be endorsed with a requirement or limitation when safe flying depends on it, for example wearing corrective lenses. Regulation 67.00.6(5) also lets the examiner or SACAA's medical assessor shorten the validity period, for instance so that a condition is reviewed more often."},{t:"p",x:"Regulation 67.00.8(4A) goes further. In exceptional circumstances SACAA's medical assessor may issue or renew a certificate for someone who does not meet some of the standards, if accredited medical conclusion shows that flying is not likely to jeopardise safety, taking account of the person's ability, skill, experience and operating conditions. Any limitation that safety depends on is endorsed on the licence."},{t:"h2",x:"Can I appeal a decision?",id:"appeal"},{t:"p",x:"Yes. SACAA procedure AM007 says applicants who are aggrieved by the decision of a designated examiner, an authorised officer or the designated body may appeal to the Director of Civil Aviation within **30 days**, as prescribed in Part 67. If SACAA suspends a certificate, regulation 67.00.14 sets a shorter period: an appeal within 14 days of the suspension."},{t:"h2",x:"What must I report between medicals?",id:"report"},{t:"p",x:"Your duties do not stop at the examination. Regulation 67.00.9 says you may not act as a pilot, air traffic service member or cabin crew member while you know of a medical condition or medicine that could affect your certificate, or once it has expired. You must also tell SACAA without undue delay about any:"},{t:"ul",items:["Hospital admission","Surgical operation or invasive procedure","Regular use of medicine","The need to use correcting lenses for the first time, or a change of lenses","An injury or illness that keeps you from exercising the privileges of your licence"]},{t:"p",x:"That applies where the event means you no longer meet the medical standards. Before you fly again you must give SACAA proof that you have fully recovered. If you are unsure whether something counts, ask your examiner. AM007 says every applicant is responsible for consulting their DAME about medical conditions or medicines being considered, to make sure they are compatible with flying."},{t:"h2",x:"How can I keep a deferral from dragging on?",id:"short"},{t:"ul",items:["Answer the history questions on the SACAA form fully. You sign a declaration that they are accurate, complete and true.","Bring recent reports if you already have a known condition.","Once a further report is requested, arrange it promptly. Examination results may only be used for 90 days.","If a case is going to the Aeromedical Committee, AM007 says documents must be in at least seven days before the meeting, which is on the third Tuesday of each month."]},{t:"p",x:"For a routine renewal with no outstanding reports, see [how to renew a Class 2 medical](/blog/renew-sacaa-class-2-medical/) or [book an appointment](/book/)."},{t:"cta",x:"Book your aviation medical"}],faq:[{q:"Does a deferred medical mean I failed?",a:"No. A deferral means the examiner cannot issue the certificate until further information is in, or until SACAA gives an instruction. It is not the same as being declared unfit."},{q:"When does the SACAA Aeromedical Committee meet?",a:"SACAA procedure AM007 says the committee meets on the third Tuesday of each month, and documents must be submitted at least seven days before the meeting."},{q:"How long are my medical examination results valid for?",a:"Regulation 67.00.12 says examination records may be used to issue a certificate for no more than 90 days. After that the examination may need to be repeated."},{q:"How long do I have to appeal a medical decision?",a:"SACAA procedure AM007 says you may appeal to the Director of Civil Aviation within 30 days. An appeal against a suspension must be made within 14 days, under regulation 67.00.14."},{q:"Can I fly while taking medicine?",a:"Not while you know of a medicine or condition that could affect your certificate. Regulation 67.00.9 also requires you to report regular use of medicine. Ask your DAME before you fly."}],sources:[e.designation,e.am007,e.protocols,e.records,e.validityReg,e.issuing,e.suspension,e.duties,e.application]},c={slug:"what-is-included-in-a-sacaa-aviation-medical",title:"What Is Included in a SACAA Aviation Medical? | ClinoTrend",h1:"What is included in a SACAA aviation medical? Tests, history and what happens on the day",description:"What a SACAA aviation medical includes: history, examination, ECG, vision, hearing and urine tests, and which extra tests depend on your class and age.",excerpt:"What a SACAA aviation medical includes: history, examination, and the on-site tests at ClinoTrend, plus which extra tests depend on class, age and history.",keyword:"what is included in an aviation medical",question:"What is included in a SACAA aviation medical?",answer:"A SACAA aviation medical is a history, a physical examination and a set of tests, not a pass or fail quiz. At ClinoTrend, a resting ECG, vision testing, a hearing test and urine screening are done on site. Extra tests are added only when class, age or history requires them. The examiner then issues or defers the certificate.",facts:["At ClinoTrend a resting ECG, vision testing, a hearing test and urine screening are done on site.","Extra tests are added only when class, age or history requires them.","Aviation medicals start from R1,500. Extra tests or reports are added only if they are needed."],secondary:["what is involved in an aviation medical exam","what does an aviation medical exam consist of","aviation medical tests","ecg aviation medical"],published:"2026-11-11",updated:"2026-11-11",status:"draft",tag:"Tests",body:[{t:"note",x:'Primary keyword "what is included in an aviation medical" (also "what is involved in an aviation medical exam", "what does an aviation medical exam consist of"). Volume: no volume source. Source: Google Autocomplete, gl=za, 10 November 2026. Supporting terms "aviation medical tests" and "ecg aviation medical" also completed in that check. Ruben can run the 61 terms in `/workspace/seo-aeo/clinotrend/keyword-planner-upload.csv` in Keyword Planner for South Africa (Gauteng if the tool allows) and send the export back.'},{t:"p",x:"This is general information about SACAA medical certification. It is not individual medical advice, and it does not promise that anyone will be found fit. ClinoTrend issues Class 2 and Class 4 medicals only."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"A designated examiner takes your history, examines you, and records the findings on the SACAA Aviation Medical Report, form CA 67-02(a). At this practice the on-site tests are a resting ECG, vision testing, audiometry and urine screening, as already stated on the [aviation medicals page](/aviation-medicals/). Further tests are added only when they are needed. If you meet the standards and no further reports are required, the certificate can usually be issued on the day. That is not a promise for every case."},{t:"h2",x:"Before you arrive",id:"before-you-arrive"},{t:"p",x:"Book the class that matches your licence: Class 2 for most student and private pilots, Class 4 for many cabin crew and recreational licences. Complete the [SACAA application form](/sacaa-form/) before you arrive. It is sent only to the practice. Bring proof of identity, your licence and current certificate if you have them, a list of medicines, and your glasses or contact lenses."},{t:"p",x:"The full packing list and directions sit in the live [Midrand and Johannesburg guide](/blog/aviation-medical-midrand-johannesburg/). For a preparation checklist, including what to do the day before, see [how to prepare for a SACAA aviation medical](/blog/how-to-prepare-for-a-sacaa-aviation-medical/). [Book online](/book/), or call 011 568 7979 or WhatsApp 078 255 1405."},{t:"h2",x:"History and examination",id:"history-and-examination"},{t:"p",x:"Regulation 67.00.7 requires you to give the examiner your medical history and to sign a declaration that the information is accurate, complete and true. Form CA 67-02(a) records height, mass and body mass index, seated blood pressure, resting pulse, and the examination findings. Tell the examiner about medicines, operations, hospital visits and any condition you are being treated for, including pharmacy products."},{t:"p",x:"An honest history is not a trap. It is how the examiner decides whether the on-site tests are enough, or whether a report is needed. If more information is required, the usual next step is a deferral, which is explained in [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/)."},{t:"h2",x:"Tests done on site at ClinoTrend",id:"tests-done-on-site-at-clinotrend"},{t:"p",x:"On the live aviation medicals page, this practice lists four tests done on site:"},{t:"ul",items:["a resting ECG","vision testing","a hearing test (audiometry)","urine screening"]},{t:"p",x:"Those are the tests you should expect at a Class 2 or Class 4 visit here, unless the doctor has told you something different when you booked. Colour perception is recorded as part of the visual examination on form CA 67-02(a), usually with pseudo-isochromatic plates. See [SACAA pilot eyesight and colour vision](/blog/sacaa-pilot-eyesight-colour-vision/) for that part of the exam."},{t:"confirm",x:"Please confirm that a resting ECG, vision testing, audiometry and urine screening are still done on site at every Class 2 and Class 4 visit, or say when an exception applies."},{t:"h2",x:"Tests that are not always done here",id:"tests-that-are-not-always-done-here"},{t:"p",x:"Form CA 67-02(a) also has fields for a stress (exercise) ECG, a lung function test, a lipogram and a chest X-ray. Those are special investigations. They are used when class, age or history requires them, or when a SACAA protocol asks for them. They are not described on the live site as automatic for every visit, and this article does not invent a rule for when a chest X-ray or a stress ECG is done."},{t:"p",x:"If a further test or a specialist report is needed, the examiner will tell you whether it is done on site or referred. Aviation medicals start from R1,500. Extra tests or reports are added only if they are needed. The fee is confirmed when you book. See [how much a SACAA aviation medical costs](/blog/aviation-medical-cost-south-africa/)."},{t:"confirm",x:'Please confirm any chest X-ray, exercise ECG or other referral rule you want stated, including whether a chest X-ray is routine at a first Class 2. If you would rather we say only "we will tell you when you book", we will keep it that way.'},{t:"h2",x:"Class 1 and Class 3 are different visits",id:"class-1-and-class-3-are-different-visits"},{t:"p",x:"Class 1 (commercial and airline transport pilots) and Class 3 (air traffic services) must be done by a Senior Designated Aviation Medical Examiner. Dr A.O. Ndhlovu is a Regular DAME (MR 336) and issues Class 2 and Class 4 only. ClinoTrend does not offer Class 1 or Class 3 bookings. If you need Class 1, read [SACAA Class 1 medical: who needs it, and a Senior DAME](/blog/sacaa-class-1-medical-senior-dame/) and use the official list on the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/)."},{t:"h2",x:"After the exam",id:"after-the-exam"},{t:"p",x:"If you meet the standards and no further reports are needed, the certificate can usually be issued at the end of the examination. SACAA procedure AM007 describes two copies with the same serial number: the yellow copy goes to SACAA and you keep the white copy with you while flying. If more information is needed, the examiner may defer the certificate, or issue it with a limitation or a shorter validity under regulation 67.00.6(5)."},{t:"p",x:"Ask the practice how long to allow when you book. A duration is not published here, because the live site no longer quotes a single 30 to 60 minute figure."},{t:"confirm",x:'Please confirm whether you want any time-range for the visit stated. If not, we will keep "ask when you book".'},{t:"p",x:"Ready to book a Class 2 or Class 4 medical? Complete the [SACAA form](/sacaa-form/), then [choose a time](/book/). Or call 011 568 7979 or WhatsApp 078 255 1405."},{t:"cta",x:"Book your Class 2 or Class 4 medical"}],faq:[{q:"What tests are done at an aviation medical?",a:"A history and physical examination, and, at ClinoTrend, a resting ECG, vision testing, a hearing test and urine screening on site. Extra tests are added only if they are required for your class, age or history."},{q:"Do I always need an ECG?",a:"A resting ECG is done on site at this practice. Whether that is every Class 2 and Class 4 visit is marked for the doctor to confirm."},{q:"Do I need a chest X-ray?",a:"Not automatically, on the information published on the live site. The examiner will tell you if one is needed. This is marked for the doctor to confirm."},{q:"How long does it take?",a:"Ask when you book. This article does not quote a time range unless the doctor confirms one."},{q:"Will I get my certificate the same day?",a:"Usually, if no further reports are needed. That is not a promise."},{q:"Can ClinoTrend do a Class 1 medical?",a:"No. Class 1 and Class 3 need a Senior DAME. See the Class 1 guide and the [DAME post](/blog/sacaa-medical-examiners-dame/)."}],sources:[e.form,e.application,e.validityReg,e.am007,e.avmed,e.register]},h={slug:"aviation-medical-cost-south-africa",title:"SACAA Aviation Medical Cost in South Africa | ClinoTrend",h1:"How much does a SACAA aviation medical cost in South Africa?",description:"What a SACAA aviation medical costs, what the starting fee includes, and why Class 1 visits, extra reports and further tests can change the total.",excerpt:"What a SACAA aviation medical costs at ClinoTrend: the starting fee from R1,500, what may be included, and why extra tests or a Class 1 visit can change the total.",keyword:"how much is an aviation medical",question:"How much does a SACAA aviation medical cost in South Africa?",answer:"At ClinoTrend, aviation medicals start from R1,500. The starting fee is confirmed when you book. Extra tests or specialist reports are added only if they are needed for your class, age or history. Class 1 medicals are done by a Senior DAME at another practice, so their fees are separate.",facts:["Aviation medicals at ClinoTrend start from R1,500. The fee is confirmed when you book.","Extra tests or reports are added only if they are needed for your class, age or history.","Class 1 medicals are done by a Senior DAME at another practice. This practice does not quote that fee."],secondary:["how much is an aviation medical exam","how much is a class 1 aviation medical","aviation medical cost","class 2 medical certificate cost"],published:"2026-11-11",updated:"2026-11-11",status:"draft",tag:"Cost",body:[{t:"note",x:'Primary keyword "how much is an aviation medical" (also "how much is an aviation medical exam", "how much is a class 1 aviation medical"). Volume: no volume source. Source: Google Autocomplete, gl=za, 10 November 2026. Some suggestions were medical-flight or air-ambulance prices; those are ignored. Secondary: "aviation medical cost" also completed under Pretoria and Centurion seeds in the same check. Ruben can run the Keyword Planner upload file for South Africa (Gauteng if possible) and send the export back.'},{t:"p",x:"This page is about fees at this practice for Class 2 and Class 4 medicals. It is not a price list for every DAME in South Africa, and it is not a quote for a Class 1 visit."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"The live site states that aviation medicals start from R1,500, and that the fee is confirmed when you book. Extra tests or reports are added only if the doctor finds they are needed during the medical. Payment by EFT or card is required at the time of your visit. The practice accepts most medical aids and charges medical aid rates. Self-pay patients receive a quote before treatment. Bring your medical aid card if you use one."},{t:"confirm",x:"Please confirm that the starting fee, payment (EFT or card at the visit), and medical aid wording are still current."},{t:"p",x:"For location, parking and what to bring, use the [Midrand and Johannesburg guide](/blog/aviation-medical-midrand-johannesburg/). The service page at [/aviation-medicals/cost/](/aviation-medicals/cost/) also covers the starting fee. This article is the dedicated cost guide for people comparing fees nationally."},{t:"h2",x:"What the starting fee is meant to include",id:"what-the-starting-fee-is-meant-to-includ"},{t:"p",x:"The starting fee is meant to cover the examination and the on-site tests listed on the [aviation medicals page](/aviation-medicals/): a resting ECG, vision testing, a hearing test and urine screening. A short, exact inclusions list is not published here until the doctor confirms it. If your visit needs only those items, the starting fee is the figure to plan around, once it has been confirmed when you book."},{t:"confirm",x:"Please confirm a short inclusions list for the starting fee (what is in, and what is never in) before this paragraph is treated as final."},{t:"h2",x:"What can change the total",id:"what-can-change-the-total"},{t:"p",x:"The total can be higher than the starting fee when extra tests or specialist reports are needed. That can happen at a first medical, or at a renewal, if your history or the examination findings require them. Examples include a test that is referred out, or a report from a physician, cardiologist or ophthalmologist. This article does not invent add-on prices for those items. You will be told if something extra is needed, and the fee is confirmed when you book or when the extra work is identified."},{t:"p",x:"A straightforward renewal with no further tests is not always the same visit as a first medical with outstanding reports. The class (Class 2 or Class 4) may also affect what is required, but a different fee for each class is not published here unless the doctor confirms a split."},{t:"confirm",x:"Please confirm whether Class 2 and Class 4 have different starting fees, or whether both start from R1,500."},{t:"h2",x:"Class 1 and Class 3 fees",id:"class-1-and-class-3-fees"},{t:"p",x:`ClinoTrend does not issue Class 1 or Class 3 medicals. Those visits are done by a Senior DAME. Their fees are set by that examiner, not by this practice, and this page does not quote another clinic's Class 1 fee. If you are searching "how much is a class 1 aviation medical", read [SACAA Class 1 medical: who needs it, and a Senior DAME](/blog/sacaa-class-1-medical-senior-dame/) and use the official Senior DAME list on the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/).`},{t:"h2",x:"Medical aid",id:"medical-aid"},{t:"p",x:"Medical aid cover differs between services and plans. Please check with the practice before your visit and bring your medical aid card. Self-pay patients receive a quote before treatment. That wording follows the live FAQ. It is not a promise that every plan will pay the full fee."},{t:"h2",x:"How to get a confirmed figure",id:"how-to-get-a-confirmed-figure"},{t:"p",x:"[Book a Class 2 or Class 4 medical](/book/), or call 011 568 7979 or WhatsApp 078 255 1405 and say which class you need. For group bookings for a flight school, email info@clinotrend-health.co.za. The practice is at Grand Central Airport, Gate 2, Office TG6B, Midrand, and is by appointment only."},{t:"confirm",x:"Please confirm the deferral payment policy (whether the starting fee is still payable if the certificate is deferred for reports)."},{t:"cta",x:"Get a confirmed fee, or book a Class 2 or Class 4 medical"}],faq:[{q:"How much does an aviation medical cost at ClinoTrend?",a:"Aviation medicals start from R1,500. The fee is confirmed when you book. Extra tests or reports are added only if they are needed."},{q:"Is a Class 4 cheaper than a Class 2?",a:"This article does not publish a split unless the doctor confirms one. Ask when you book."},{q:"Does medical aid pay for an aviation medical?",a:"Often in part, depending on the plan. Check with the practice before you come, and bring your card."},{q:"Why was I quoted more than the starting fee?",a:"Extra tests or reports may have been needed for your class, age or history."},{q:"How much is a Class 1 medical in South Africa?",a:"It depends on the Senior DAME. ClinoTrend does not issue Class 1 and does not quote that fee."},{q:"Do I pay if the certificate is deferred?",a:"This is marked for the doctor to confirm, so that the answer is honest and precise."}],sources:[e.avmed,e.register]},m={slug:"sacaa-class-1-medical-senior-dame",title:"SACAA Class 1 Medical and Senior DAMEs | ClinoTrend",h1:"SACAA Class 1 medical: who needs it, how long it lasts, and who can issue it",description:"Who needs a SACAA Class 1 medical, that only a Senior DAME can issue it, and how to use the official examiner list. ClinoTrend issues Class 2 and 4 only.",excerpt:"Who needs a SACAA Class 1 medical, why only a Senior DAME can issue it, and how to use the official examiner list. ClinoTrend issues Class 2 and 4 only.",keyword:"sacaa class 1 medical",question:"Who needs a SACAA Class 1 medical, and who can issue it?",answer:"A SACAA Class 1 medical is the certificate commercial and airline transport pilots need. In South Africa only a Senior Designated Aviation Medical Examiner can issue it. A Regular DAME, including Dr A.O. Ndhlovu at ClinoTrend, issues Class 2 and Class 4 medicals only. Use the SACAA Senior DAME list to find the right examiner.",facts:["A SACAA Class 1 medical can be issued only by a Senior Designated Aviation Medical Examiner.","Dr A.O. Ndhlovu is a Regular DAME, MR 336, and issues Class 2 and Class 4 medicals only.","Use the official Senior DAME list on the SACAA Aviation Medicine page to find the right examiner."],secondary:["sacaa class 1 medical requirements","class 1 medical certificate south africa","class 1 medical validity","cpl medical requirements south africa"],published:"2026-11-11",updated:"2026-11-11",status:"draft",tag:"Class 1",body:[{t:"note",x:'Primary keyword "sacaa class 1 medical" (also "sacaa class 1 medical certificate", "class 1 medical certificate south africa"). Volume: no volume source. Source: Google Autocomplete, gl=za, 10 November 2026. "atpl medical requirements south africa" and "cpl medical requirements south africa" returned no suggestions in that check (no volume source). Ruben can run the Keyword Planner upload file and send the export back.'},{t:"p",x:"This is an educational guide, not a service page. ClinoTrend does not offer Class 1 or Class 3 bookings."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"If you need a Class 1 medical, you need a Senior DAME. That is stated on the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/) and on this practice's [aviation medicals page](/aviation-medicals/). Regular DAMEs are authorised for Class 2 and Class 4. Senior DAMEs are authorised for Class 1, 2, 3 and 4. For the wider class table, see [SACAA aviation medical classes explained](/blog/sacaa-medical-classes-explained/). For how to check an examiner, see [SACAA medical examiners](/blog/sacaa-medical-examiners-dame/)."},{t:"h2",x:"Who needs Class 1",id:"who-needs-class-1"},{t:"p",x:"The SACAA Aviation Medicine page describes Class I medical certificate holders as including airline transport and commercial pilots. The amended Part 67 regulation 67.00.2, on classes of medical certificates, is the regulation to check for the official licence list. This article does not invent extra licence types. If you are applying for a commercial pilot licence or an airline transport pilot licence, you should expect to need Class 1, and you should confirm that against the official table and your licensing file."},{t:"p",x:"A valid Class 1 certificate is deemed to cover Class 2 and Class 4 privileges, under regulation 67.00.2. The reverse is not true: a Class 2 certificate does not stand in for Class 1."},{t:"h2",x:"Why a Regular DAME cannot do it",id:"why-a-regular-dame-cannot-do-it"},{t:"p",x:"The Director designates examiners in two categories that matter here. Regular Designated Aviation Medical Examiners may examine for and issue Class 2 and Class 4. Senior Designated Aviation Medical Examiners may examine for and issue Class 1, 2, 3 and 4. Dr A.O. Ndhlovu is listed as a Regular DAME, MR 336, at Grand Central Airport, Midrand. He cannot issue a Class 1 medical. Please do not book a Class 1 slot here; there is not one."},{t:"h2",x:"How to find a Senior DAME",id:"how-to-find-a-senior-dame"},{t:"p",x:"Open the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/) and use the current list of Senior Designated Aviation Medical Examiners. The exact PDF address on that page can change, so this article links the page rather than a file that may go stale. Check that the examiner is on the current Senior list, and is designated for the class you need, before you book."},{t:"p",x:"If you are a student or a private pilot now, you can still do your Class 2 medical at ClinoTrend. When you later need Class 1 for commercial training or a professional licence, you move to a Senior DAME. Bring your last certificate and any reports with you."},{t:"h2",x:"Validity, carefully",id:"validity-carefully"},{t:"p",x:"Class 1 validity is set in Part 67, regulation 67.00.6(1), which we opened for this draft. In outline, a Class 1 certificate is issued for:"},{t:"ul",items:["12 months, where the applicant is less than 40 on the date it is issued","6 months, for an airline transport pilot in single-crew commercial air transport operations, where the applicant is 40 or more","12 months, for an airline transport pilot in multi-crew commercial air transport operations, where the applicant is 40 or more but less than 60","12 months, for a commercial pilot, where the applicant is 40 or more but less than 60","6 months, for the pilots described in those last two bullets, where the applicant is 60 or more"]},{t:"p",x:"The periods are calculated from the last day of the calendar month in which the certificate is issued. Regulation 67.00.6(2) also sets follow-up conditions for some Class 1 holders aged 40 or more. Older SACAA FAQ pages have, in the past, used wording that does not always match the regulation. This practice follows the regulation for Class 2 and Class 4 on the live site. The same approach is used here for Class 1, and the figures are marked for the doctor to confirm before they are treated as final. Do not mix FAA, DGCA or EASA periods into this table."},{t:"confirm",x:"Please confirm the Class 1 validity table above against Part 67, regulation 67.00.6, and against the current SACAA FAQ, and the wording you want when we signpost patients to a Senior DAME."},{t:"h2",x:"What ClinoTrend can still help with",id:"what-clinotrend-can-still-help-with"},{t:"p",x:"ClinoTrend remains the right place for Class 2 and Class 4 medicals: student and private pilots, many cabin crew, and recreational licences that sit under Class 4. For what happens at those visits, see [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/). [Book a Class 2 or Class 4 medical](/book/), or call 011 568 7979 or WhatsApp 078 255 1405. If you need Class 1, use the SACAA Senior DAME list, not this booking form."},{t:"cta",x:"Book a Class 2 or Class 4 medical, or find a Senior DAME for Class 1"}],faq:[{q:"Can ClinoTrend do my Class 1 medical?",a:"No. You need a Senior DAME. Use the official list on the SACAA Aviation Medicine page."},{q:"Who needs a Class 1 medical in South Africa?",a:"Commercial and airline transport pilots, as described on the SACAA Aviation Medicine page. Confirm your licence against the official class table."},{q:"How long is a SACAA Class 1 medical valid?",a:"Part 67, regulation 67.00.6(1), sets periods of 12 or 6 months depending on age and the type of operation. The table in this article is marked for the doctor to confirm, especially where an older FAQ page may differ."},{q:"What is the difference between Class 1 and Class 2?",a:"The licence it supports, the examiner who can issue it, and some of the standards and intervals. A Regular DAME cannot issue Class 1."},{q:"I already had a Class 2 here. What now?",a:"Book a Senior DAME for Class 1. Bring your last certificate and any reports."},{q:"How much is a Class 1 medical?",a:"Set by that examiner. This practice does not quote it."}],sources:[e.avmed,e.classesReg,e.validityReg,e.faq,e.register]},u={slug:"sacaa-pilot-eyesight-colour-vision",title:"SACAA Pilot Eyesight and Colour Vision | ClinoTrend",h1:"SACAA pilot eyesight and colour vision: what the standards say, and what happens if you do not meet them at first",description:"What SACAA requires for vision and colour perception, how the first colour-plate test works, and why a fail is not always the end of a flying career.",excerpt:"What SACAA aviation medicals include for vision and colour perception, how the first colour-plate test works, and why numeric limits wait for official sign-off.",keyword:"colour vision test pilot south africa",question:"What are the SACAA eyesight and colour vision requirements for pilots?",answer:"SACAA aviation medicals include vision and colour-perception tests. Many people who wear glasses can still meet the standard. If you do not pass the first colour-plate test, that is not automatically the end: further testing may be required, and some restrictions can apply. Only the official standards and the examiner's assessment decide the outcome.",facts:["Vision testing is done on site at ClinoTrend for Class 2 and Class 4 medicals.","Form CA 67-02(a) records acuity, colour perception and contact-lens conditions (monofocal, non-tinted, spare spectacles).","This article does not publish acuity or colour-test numbers until an official source is opened and the doctor signs them off."],secondary:["pilot eyesight requirements south africa","colour vision test pilot south africa","can you be a pilot with glasses","ishihara test pilot"],published:"2026-11-11",updated:"2026-11-11",status:"draft",tag:"Vision",body:[{t:"note",x:'Primary keywords "colour vision test pilot south africa" and "pilot eyesight requirements south africa". Volume: no volume source. Source: exact South African phrases returned no Google Autocomplete suggestions on 10 November 2026 (gl=za). Demand is inferred from parent exam queries in "what is included in an aviation medical", which did complete in that check, and from standard questions people ask. This is not a volume figure. Ruben can run the Keyword Planner upload file and send the export back.'},{t:"p",x:"This is general information, not a personal assessment, and it does not promise fitness. This article does not publish acuity, colour-vision or test-score numbers, because the official technical standards were not opened as a complete CATS 67 document for this draft, and unofficial clinic tables are not the law."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"Vision and colour perception are part of every SACAA aviation medical. At ClinoTrend, vision testing is done on site, as stated on the [aviation medicals page](/aviation-medicals/). Form CA 67-02(a) records visual acuity (with and without correction, each eye and both eyes, for distant, intermediate and near vision), colour perception, visual fields, ocular muscle balance and other eye findings. The examiner applies the official standard to you. A blog post cannot tell you whether you will meet it."},{t:"h2",x:"Distance, near and intermediate vision",id:"distance-near-and-intermediate-vision"},{t:"p",x:"The visual standard sits in Part 67 and the associated technical standards. We have opened form CA 67-02(a) and the summarised medical protocols list, but we have not opened a complete official CATS 67 visual-requirement clause that we can quote as a numeric limit. This article therefore does not publish acuity figures such as a 6/6 or 6/9 standard, or any unofficial number copied from another clinic's website. Those figures, if they appear elsewhere, must be checked against the official text."},{t:"p",x:"What we can say from the form itself is that both uncorrected and corrected acuity are recorded, for each eye and for both eyes, at distant, intermediate and near distances. Correction, if you use it, is part of the examination, not a surprise. If the official wording is later confirmed, it can be added with a citation and the doctor's sign-off."},{t:"confirm",x:"Please confirm any acuity wording you want published, quoted only from an official SACAA protocol or CATS 67 clause you are willing to cite. Until then, we will not print numeric limits."},{t:"h2",x:"Glasses and contact lenses",id:"glasses-and-contact-lenses"},{t:"p",x:"Many people who wear glasses or contact lenses can still meet the standard, if the corrected vision required by the official text is met. That is not a promise that every prescription will be accepted. Form CA 67-02(a), which we opened, already notes conditions for contact-lens use: monofocal, non-tinted lenses, and spare spectacles. Bring your current glasses or lenses, and a spare pair if you have one. A recent optometrist or ophthalmologist report can help, but it does not replace the aviation medical."},{t:"h2",x:"Colour perception",id:"colour-perception"},{t:"p",x:"Colour perception is recorded on the same form, usually first with pseudo-isochromatic plates (often called an Ishihara test). If you do not pass that first test, that is not automatically the end of a flying career. Further testing may be required, and some restrictions can apply, depending on the official protocol and the results. This article does not paste pass marks, plate counts or clinic-specific colour-test thresholds, including figures that appear on unofficial DAME websites. Those pages are not the law."},{t:"p",x:"Some unofficial pages also discuss a further colour-assessment test after the plates. We will only describe that test, and any pass mark, if the doctor confirms it from a SACAA document that has been opened, and signs the wording off."},{t:"confirm",x:"Please confirm whether colour testing beyond plates (for example a further assessment such as CAD) is done on site at ClinoTrend or by referral, and whether any official threshold should be quoted. Until then, no numbers will be published."},{t:"h2",x:"If you do not meet the standard at first",id:"if-you-do-not-meet-the-standard-at-first"},{t:"p",x:"If a finding needs more information, the usual first step is a deferral or a limitation, not a lifetime ban. Complex cases can be referred to the Aeromedical Committee. That process is explained in [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/) and in the companion article [what can defer or limit a SACAA medical](/blog/what-can-defer-or-limit-a-sacaa-medical/). This page does not promise that you will still obtain any particular licence."},{t:"h2",x:"What happens at ClinoTrend",id:"what-happens-at-clinotrend"},{t:"p",x:"Vision testing is on site for Class 2 and Class 4 medicals. Class 1 eye standards, and the issue of a Class 1 certificate, sit with a Senior DAME, not with this practice. See [SACAA Class 1 medical and Senior DAMEs](/blog/sacaa-class-1-medical-senior-dame/). If you are booking a Class 2 or Class 4 medical, [book online](/book/), or call 011 568 7979 or WhatsApp 078 255 1405, and bring your glasses or lenses and any recent eye reports."},{t:"confirm",x:"Preferred wording so the page cannot be read as a promise of fitness."},{t:"cta",x:"Book your Class 2 or Class 4 medical"}],faq:[{q:"Can I be a pilot if I wear glasses?",a:"Many people can, if the corrected official standard is met. Only the examination can apply that standard to you."},{q:"What is the SACAA eyesight requirement?",a:"See Part 67 and the technical standards. This article does not publish a numeric limit until an official clause is opened and the doctor signs it off."},{q:"What if I fail the Ishihara plates?",a:"Further testing may be required. This page does not predict the result."},{q:"Can I be a commercial pilot with a colour-vision deficiency?",a:"Sometimes, with limits, depending on the official protocol and the test results. This page does not promise an outcome."},{q:"Should I get an eye test before my medical?",a:"It can be useful to bring a recent report. It does not replace the aviation medical."},{q:"Does ClinoTrend do Class 1 eye standards?",a:"Class 1 is issued only by a Senior DAME. We do Class 2 and Class 4 vision testing here."}],sources:[e.form,e.avmed,{...e.protocols,name:"SACAA Summarised Medical Protocols in line with Part 67 (effective 16 November 2021), item 47 (PRK and LASIK)"}]},f={slug:"blood-pressure-diabetes-medication-sacaa-medical",title:"Blood Pressure, Diabetes and Medicines | ClinoTrend",h1:"Blood pressure, diabetes and medicines: what to tell your SACAA examiner",description:"How high blood pressure, diabetes and everyday medicines are handled at a SACAA aviation medical, and why you must declare them. Not personal advice.",excerpt:"How high blood pressure, diabetes and everyday medicines are handled at a SACAA medical, and why every diagnosis and medicine must be declared. Not personal advice.",keyword:"can you be a pilot with high blood pressure",question:"Can you fly with high blood pressure, diabetes or everyday medicines at a SACAA medical?",answer:"High blood pressure, diabetes and many everyday medicines are not an automatic no at a SACAA medical, and they are not an automatic yes either. Declare every medicine and every diagnosis. The examiner applies the official protocols to your case, and may need reports from your own doctor before a certificate can be issued.",facts:["High blood pressure, diabetes and many everyday medicines are not an automatic no, and not an automatic yes.","Declare every medicine and every diagnosis. The examiner applies the official protocols and may need reports.","This article does not publish blood-pressure or glucose numbers."],secondary:["hypertension aviation medical","blood pressure aviation medical","diabetes aviation medical","can you be a pilot with diabetes"],published:"2026-11-11",updated:"2026-11-11",status:"draft",tag:"Conditions",body:[{t:"note",x:'Primary cluster "hypertension aviation medical", "blood pressure aviation medical", "can you be a pilot with high blood pressure". Volume: no volume source. Source: Google Autocomplete, gl=za, 10 November 2026, including "aviation medical blood pressure limits" (some suggestions were FAA-skewed; this article answers in SACAA terms only). Secondary cluster "diabetes aviation medical", "can you be a pilot with diabetes" also completed in that check. "medication and flying south africa" returned no suggestions (no volume source) and is still covered below. Ruben can run the Keyword Planner upload file and send the export back.'},{t:"p",x:"This is general information, not individual medical advice, and it does not promise fitness. This article does not publish blood-pressure or glucose numbers."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"These are among the most common questions before a first medical, or before a renewal after a new diagnosis. The honest answer is that compatibility depends on the condition, how it is treated, the official protocol, and the findings on the day. A blog post cannot decide your case. If more information is needed, the usual next step is a deferral, explained in [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/)."},{t:"h2",x:"Always declare",id:"always-declare"},{t:"p",x:'Regulation 67.00.7 and form CA 67-02(a) require a complete history, including medicines. That includes prescription medicines, pharmacy products and anything you take regularly. Incomplete disclosure is itself a problem for certification. It is also a poor way to start a medical relationship with an examiner. Do not start, stop or hide a medicine in order to "pass". Ask your treating doctor before you change anything, and tell the examiner what you take.'},{t:"h2",x:"Blood pressure",id:"blood-pressure"},{t:"p",x:"Seated blood pressure is recorded on form CA 67-02(a). The summarised SACAA medical protocols, dated 16 November 2021, which we opened, include a named protocol for hypertension (item 27). That protocol list does not, in the summary we opened, give a numeric cut-off that this article can quote. Unofficial pages, and many FAA blogs, publish figures that must not be copied here."},{t:"p",x:"If your blood pressure needs attention, the examiner may ask for a report from your own doctor, further readings, or other investigations listed in the protocol. Controlled high blood pressure can be compatible with certification in some cases. Uncontrolled high blood pressure, or a related complication, may lead to a deferral or a finding that more work is needed. Only the examination can decide."},{t:"confirm",x:"Please confirm that no numeric blood-pressure limit should be published, or quote the official protocol figure if you want one cited, with the source."},{t:"h2",x:"Diabetes",id:"diabetes"},{t:"p",x:`SACAA distinguishes types of diabetes and types of treatment. The summarised protocols include a Type II diabetes protocol (item 33). The [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/), which we opened, discusses significant incapacitation risk at the initial examination, and gives Type 1 diabetes as an example of a condition that is screened out at that stage. That is SACAA's wording, not a clinic slogan, and it is not a personal prediction for every applicant. This article does not say "Type 1 can never fly" as a blanket clinic rule, and it does not say "Type 2 is always fine".`},{t:"p",x:"If you have diabetes, bring recent reports from your treating doctor. The examiner applies the current protocol to your case, and may defer the certificate for further information or a committee review. Glucose numbers are not published here."},{t:"confirm",x:"Please confirm the preferred wording for Type 1 diabetes, staying with the Aviation Medicine page if that is what you want, and confirm that no glucose figures should be published."},{t:"h2",x:"Medicines",id:"medicines"},{t:"p",x:'Some medicines are acceptable in aviation, some need a waiting period after a change, and some are not compatible with the duties of the certificate. This practice has not been given a short, official allowed-list to publish, and there is no verified public "banned list" that we have opened and can reprint. The default advice is simple: bring the box or a written list, including doses, and do not start or stop a medicine to influence the exam.'},{t:"p",x:"If you take a medicine for mood, sleep, attention, pain or another long-term condition, declare it. The next article, [what can defer or limit a SACAA medical](/blog/what-can-defer-or-limit-a-sacaa-medical/), explains how those findings are handled in general terms."},{t:"confirm",x:'Please confirm whether you want any medicine classes named from an official SACAA "acceptable medication" source. Default: no named list.'},{t:"h2",x:"What ClinoTrend will do",id:"what-clinotrend-will-do"},{t:"p",x:"At a Class 2 or Class 4 visit, the examiner takes the history, examines you, and decides whether the on-site tests are enough. If reports are needed, you will be told clearly. The practice cannot promise a certificate in advance. If you already know a report will be useful, ask when you [book](/book/), or call 011 568 7979 or WhatsApp 078 255 1405, and see [how to prepare for a SACAA aviation medical](/blog/how-to-prepare-for-a-sacaa-aviation-medical/)."},{t:"cta",x:"Book your Class 2 or Class 4 medical"}],faq:[{q:"Can I fly if I have high blood pressure?",a:"Sometimes, if it is controlled and the protocol is met. Only an examination can decide."},{q:"What blood pressure is acceptable?",a:"This article does not quote a figure. The examiner applies the current official protocol."},{q:"Can I be a pilot if I have diabetes?",a:"It depends on the type, the treatment and the protocol. This page does not promise an outcome."},{q:"Should I stop my medicine before the medical?",a:"No. Ask your treating doctor and tell the examiner."},{q:"Will I fail if I take antidepressants or other regular medicines?",a:"This page does not answer yes or no. Declare them. See the deferral and limits guide, and the deferred-medical post."},{q:"Can this be done at ClinoTrend?",a:"Class 2 and Class 4 medicals, yes. Complex cases may be deferred. Class 1 needs a Senior DAME."}],sources:[e.form,{...e.protocols,name:"SACAA Summarised Medical Protocols in line with Part 67 (effective 16 November 2021), item 33 (Diabetes Mellitus Type II)"},e.avmed,e.application]},p={slug:"what-can-defer-or-limit-a-sacaa-medical",title:"What Can Defer or Limit a SACAA Medical? | ClinoTrend",h1:"What can defer or limit a SACAA medical, and what that is not",description:"Medical conditions and findings that can defer or limit a SACAA certificate, how the Aeromedical Committee fits in, and why a blog cannot decide your case.",excerpt:"What can defer or limit a SACAA medical certificate, why a US-style disqualify list does not apply, and how this page sits next to the live deferred-medical guide.",keyword:"what disqualifies you from a pilot medical",question:"What can defer or limit a SACAA medical certificate?",answer:"SACAA does not publish a simple fail list that a blog can apply to you. Some conditions must be declared and assessed under official protocols. The usual first step, if more information is needed, is a deferral or a limitation, not a lifetime ban. The Aeromedical Committee reviews complex cases. Only an examination can decide yours.",facts:["SACAA does not publish a simple fail list that a blog can apply to you.","The usual first step, if more information is needed, is a deferral or a limitation, not a lifetime ban.","This article is a companion to the live deferred-medical process post, not a rewrite of it."],secondary:["what medical conditions prevent you from becoming a pilot","pilot disqualifying medical conditions","depression aviation medical","aviation medical failed"],published:"2026-11-11",updated:"2026-11-11",status:"draft",tag:"Deferral",body:[{t:"note",x:'Primary keyword "what disqualifies you from a pilot medical" (also "what medical conditions prevent you from becoming a pilot"). Volume: no volume source. Source: Google Autocomplete, gl=za, 10 November 2026 (some suggestions were FAA-skewed). This article uses SACAA language: defer, limit, or find temporarily or longer-term unfit, not a US disqualifying list. "aviation medical failed" returned no suggestions in that check (no volume source). "depression aviation medical" did complete, again often FAA-skewed, and is covered carefully below. The live deferred post already owns the process query. Ruben can run the Keyword Planner upload file and send the export back.'},{t:"p",x:"This is a companion to [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/), not a rewrite of that process guide."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"Three outcomes matter here, and they are not the same:"},{t:"ul",items:["A **deferral** means the certificate is not issued yet, because more information is needed.","A **limitation** means a certificate is issued, with a restriction on how you may exercise it, or with a shorter validity under regulation 67.00.6(5).","A finding that you are **unfit**, temporarily or for a longer period, is a decision after the information is in, not a shortcut a website can take."]},{t:"p",x:'The deferred post explains the process, the paperwork and what you do next. This page explains why people search "what disqualifies you", and why that wording does not travel well from US sites into SACAA practice.'},{t:"h2",x:'Why "disqualify" is the wrong word here',id:"why-disqualify-is-the-wrong-word-here"},{t:"p",x:`US "disqualifying condition" lists, forum advice and FAA blogs are not Part 67. SACAA works through official protocols, the examiner's assessment, and, when needed, the Aeromedical Committee. Some conditions are difficult. Some are compatible once they are treated and documented. A complete fail list in a blog would be both incomplete and misleading, so this article does not offer one.`},{t:"h2",x:"Kinds of issues that often need more information",id:"kinds-of-issues-that-often-need-more-inf"},{t:"p",x:"The groups below are a map, not a catalogue of bans. Each is the sort of finding that may need a report, a further test, or a committee review. The summarised SACAA medical protocols, dated 16 November 2021, which we opened, include named items in several of these areas (for example hypertension, Type II diabetes, mood disorder, and PRK/LASIK). That list is not reproduced in full here."},{t:"ul",items:["**Heart and blood pressure.** A history of raised blood pressure, a heart procedure, or an abnormal ECG often needs a report or a protocol review. See [blood pressure, diabetes and medicines](/blog/blood-pressure-diabetes-medication-sacaa-medical/).","**Metabolic and endocrine conditions**, including diabetes. The type, the treatment and the protocol all matter. There is no automatic yes or no in this article.","**Mental health**, including symptoms of depression, anxiety or related conditions, and the medicines used to treat them. Declare them. This is not a statement that you cannot fly if you have ever been depressed.","**Neurological findings**, including blackouts, seizures or unexplained loss of consciousness, which typically need specialist input.","**Vision and hearing.** Uncorrected or corrected standards, colour perception and hearing tests can lead to a further assessment or a limitation. See [SACAA pilot eyesight and colour vision](/blog/sacaa-pilot-eyesight-colour-vision/).","**Sleep**, including diagnosed sleep apnoea, which may need treatment evidence before a certificate is issued or renewed.","**Substance use.** Regulation 67.00.13 deals with the use of psychoactive substances. Honest disclosure, and the official process, is the route. This article is not a drugs-and-alcohol policy document."]},{t:"confirm",x:"Please confirm this grouping, and any example you are willing to name. We have kept the list general on purpose."},{t:"h2",x:"Mental health, carefully",id:"mental-health-carefully"},{t:"p",x:"Form CA 67-02(a) asks about mental health history and medicines. Declare symptoms and treatment. The examiner may need a report from your treating practitioner. Some cases are reviewed by the Aeromedical Committee. Industry peer-support programmes exist; this page does not endorse a particular programme. The deferred post is the place to start if a certificate is held back for a report. Preferred wording on this subject is marked for the doctor."},{t:"confirm",x:"Please confirm the mental-health wording above, including whether you want any peer-support signpost added."},{t:"h2",x:"What you should do before you book",id:"what-you-should-do-before-you-book"},{t:"p",x:'Bring recent reports, a medicine list and, if you have them, letters from your treating doctors. Do not hide history. Do not stop a medicine to "pass". Do not expect this practice to tell you in advance whether you will be found fit. [How to prepare for a SACAA aviation medical](/blog/how-to-prepare-for-a-sacaa-aviation-medical/) has the practical checklist.'},{t:"h2",x:"How ClinoTrend handles this",id:"how-clinotrend-handles-this"},{t:"p",x:"If you meet the standards and no further reports are needed, the certificate can usually be issued on the day. That is not a promise. If something else is needed, you will be told clearly. [Book a Class 2 or Class 4 medical](/book/), or call 011 568 7979 or WhatsApp 078 255 1405. Class 1 and Class 3 medicals need a Senior DAME."},{t:"p",x:"The [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/) describes the Aeromedical Committee and appeals to the Director. Use that official page for the current process, not a summary on a blog."},{t:"cta",x:"Book a Class 2 or Class 4 medical, and bring your reports"}],faq:[{q:"What disqualifies you from a SACAA medical?",a:"There is no blog list that can decide your case. Some conditions need reports or a committee review."},{q:"If I am deferred, have I failed?",a:"No. A deferral means more information is needed. See the deferred-medical post."},{q:"Can I fly with a limitation on my certificate?",a:"You can exercise the privileges the limitation still allows. Read the certificate, and stay within it."},{q:"Should I hide a condition so I can pass?",a:"No. Incomplete disclosure is itself a problem."},{q:"Can I appeal?",a:"The SACAA Aviation Medicine page describes appeals to the Director. Follow that official process."},{q:"Can ClinoTrend tell me in advance if I will pass?",a:"No. We can tell you what to bring."}],sources:[e.avmed,e.validityReg,e.form,e.protocols]},y={slug:"aviation-medical-pretoria-centurion",title:"Aviation Medical Near Pretoria and Centurion | ClinoTrend",h1:"Aviation medical near Pretoria and Centurion: a Class 2 or Class 4 medical at Grand Central, Midrand",description:"Looking for an aviation medical in Pretoria or Centurion? Dr A.O. Ndhlovu does SACAA Class 2 and Class 4 medicals at Grand Central Airport in Midrand.",excerpt:"There is no ClinoTrend branch in Pretoria or Centurion. Class 2 and Class 4 medicals are done at Grand Central Airport in Midrand, by appointment.",keyword:"aviation medical pretoria",question:"Where can I get an aviation medical near Pretoria or Centurion?",answer:"There is no ClinoTrend branch in Pretoria or Centurion. Dr A.O. Ndhlovu does SACAA Class 2 and Class 4 medicals at Grand Central Airport in Midrand, on the N1 between Pretoria and Johannesburg. You can drive from Centurion or Pretoria, or fly in to FAGC. Book before you come; the practice is by appointment only.",facts:["The practice is at Gate 2, Office TG6B, Grand Central Airport, 3 New Road, Midrand, 1685. There is no Pretoria or Centurion branch.","Opening times are 08h00 to 16h30 Monday to Thursday, and Friday 08h00 to 14h30, by appointment only.","Aviation medicals start from R1,500. Class 1 and Class 3 need a Senior DAME."],secondary:["aviation medical examiner pretoria","aviation medical centurion","aviation medical examiner centurion","flight medical pretoria"],published:"2026-11-11",updated:"2026-11-11",status:"draft",tag:"Location",body:[{t:"note",x:'Primary keyword "aviation medical pretoria" (also "aviation medical examiner pretoria"). Volume: no volume source. Source: Google Autocomplete, gl=za, 10 November 2026, including flight medical Pretoria, plus cost, duration and requirements. Secondary: "aviation medical centurion" and "aviation medical examiner centurion" also completed in that check. "aviation medical midrand" is already targeted by the live Midrand post; this article does not retarget it. Ruben can run the Keyword Planner upload file for South Africa (Gauteng if possible) and send the export back.'},{t:"p",x:"This is a location guide for the northern Gauteng searches. The full Midrand checklist lives in the [Midrand and Johannesburg post](/blog/aviation-medical-midrand-johannesburg/). Service pages for [Pretoria](/aviation-medicals/pretoria/) and [Centurion](/aviation-medicals/centurion/) sit alongside this article and should be used for the short local answer."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"The practice address is Main Terminal Building, Gate 2, Office TG6B, Grand Central Airport, 3 New Road, Midrand, 1685. There is no Pretoria clinic and no Centurion clinic. Dr A.O. Ndhlovu is a SACAA Regular DAME, MR 336, and issues Class 2 and Class 4 medicals only."},{t:"h2",x:"How to get there from Pretoria and Centurion",id:"how-to-get-there-from-pretoria-and-centu"},{t:"p",x:"Grand Central sits on the N1 corridor between Pretoria and Johannesburg, in Midrand. Current directions, including parking and public-transport notes, are on the [contact page](/contact/). This article does not invent a drive time. If you prefer to fly in, the aerodrome is FAGC, as described on the [aviation medicals page](/aviation-medicals/)."},{t:"confirm",x:"Please confirm any preferred drive-time or parking wording you want used for Pretoria and Centurion readers. Until then, we will point to the contact page and will not publish a minute count."},{t:"h2",x:"What you can have done here",id:"what-you-can-have-done-here"},{t:"p",x:"Class 2 and Class 4 medicals only. Opening times are 08h00 to 16h30 Monday to Thursday, and Friday 08h00 to 14h30, by appointment only. Aviation medicals start from R1,500. The fee is confirmed when you book. Class 1 and Class 3 medicals need a Senior DAME; see [SACAA Class 1 medical and Senior DAMEs](/blog/sacaa-class-1-medical-senior-dame/). For what the visit includes, see [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/). For fees, see [how much a SACAA aviation medical costs](/blog/aviation-medical-cost-south-africa/)."},{t:"h2",x:"What to bring, in brief",id:"what-to-bring-in-brief"},{t:"p",x:"Bring proof of identity, your completed [SACAA form](/sacaa-form/), your licence and last certificate if you have them, a medicine list, and your glasses or lenses. The full checklist is on the Midrand post and the aviation medicals page, so it is not copied in full here."},{t:"h2",x:"Other examiners in Pretoria",id:"other-examiners-in-pretoria"},{t:"p",x:"If you would rather see a DAME closer to your home or office, use the official Regular and Senior lists on the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/). This page does not list or compare other practices, and it does not invent their hours."},{t:"p",x:'The Midrand post remains the right place for parking detail, the full "what to bring" list, and the Johannesburg-side directions. This post exists so that a search for Pretoria or Centurion reaches a clear, honest answer: the clinic is in Midrand, it is one practice, and you are welcome to book a Class 2 or Class 4 medical if that is the class you need.'},{t:"p",x:"If you are comparing fees, aviation medicals start from R1,500 and the figure is confirmed when you book. If you are comparing examiners, use the official SACAA lists rather than an unofficial directory. If you need Class 1, do not book here."},{t:"p",x:"Coming from Pretoria or Centurion? [Book a Class 2 or Class 4 medical](/book/) at Grand Central, or call 011 568 7979 or WhatsApp 078 255 1405. Walk-ins are not offered."},{t:"confirm",x:"Whether a later dedicated Pretoria landing page is planned. This brief is a blog post, not that landing page."},{t:"cta",x:"Book a Class 2 or Class 4 medical at Grand Central"}],faq:[{q:"Do you have a Pretoria or Centurion clinic?",a:"No. The practice is at Grand Central, Midrand."},{q:"Can I walk in from Pretoria?",a:"No. Book first."},{q:"Do you do Class 1 medicals?",a:"No. You need a Senior DAME."},{q:"How much does it cost?",a:"From R1,500, confirmed when you book."},{q:"Can I fly in to the medical?",a:"Yes, to FAGC, as described on the aviation medicals page."},{q:"How do I book?",a:"Online at the booking page, or by phone 011 568 7979 or WhatsApp 078 255 1405."}],sources:[e.avmed,e.register]},g={slug:"how-to-prepare-for-a-sacaa-aviation-medical",title:"How to Prepare for a SACAA Aviation Medical | ClinoTrend",h1:"How to prepare for a SACAA aviation medical, first time or renewal",description:"How to prepare for a SACAA Class 2 or Class 4 medical: what to bring, what to do the day before, and how to reduce the chance of a deferral.",excerpt:"How to prepare for a SACAA Class 2 or Class 4 medical: what to bring, what the live site says about the night before, and how honest paperwork prevents most delays.",keyword:"how to prepare for aviation medical",question:"How do I prepare for a SACAA aviation medical?",answer:'Prepare for a SACAA medical by booking the right class, completing the form, gathering your ID, licence, last certificate and medicine list, and arriving rested. Do not start, stop or hide medicines to "pass". Honest paperwork and the right documents prevent most delays, not last-minute tricks.',facts:["Book the right class, complete the SACAA form, and bring ID, licence, last certificate, a medicine list and your glasses or lenses.","The live site asks you to rest well and to avoid caffeine, tobacco and high-sugar meals beforehand, because they can affect urine and ECG results.","Do not start, stop or hide medicines to influence the exam."],secondary:["what to bring to aviation medical","aviation medical requirements","prepare for aviation medical exam","aviation medical checklist"],published:"2026-11-11",updated:"2026-11-11",status:"draft",tag:"Preparation",body:[{t:"note",x:'Primary keyword "how to prepare for aviation medical". Volume: no volume source. Source: Google Autocomplete, gl=za, 10 November 2026, also "what to bring to aviation medical" and general "aviation medical requirements". Some suggestions were FAA preparation steps; those are ignored. "what to bring to aviation medical" is already used on the live Midrand post; this article links that checklist rather than replacing it. Ruben can run the Keyword Planner upload file and send the export back.'},{t:"p",x:"This is general information for Class 2 and Class 4 visits at ClinoTrend. It is not individual medical advice, and it does not promise an outcome of a certificate."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"A calm visit starts a week before, not in the car park. Book the class that matches your licence, complete the form, collect your documents, and arrive rested. For what happens in the room, see [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/). For directions, use the [Midrand and Johannesburg guide](/blog/aviation-medical-midrand-johannesburg/)."},{t:"h2",x:"A week before",id:"a-week-before"},{t:"ol",items:["Book the correct class: Class 2 for most student and private pilots, Class 4 for many cabin crew and recreational licences. ClinoTrend does not do Class 1 or Class 3.","Complete the [SACAA application form](/sacaa-form/). It is sent only to the practice.","If you already know a specialist or GP report will be needed, request it now, rather than waiting to be deferred for it.","Put together proof of identity, your licence, your last certificate if you have one, a medicine list, and your glasses or lenses."]},{t:"h2",x:"The day before and the morning",id:"the-day-before-and-the-morning"},{t:"p",x:`The live aviation medicals page asks you to rest well, and to avoid caffeine, tobacco and high-sugar meals beforehand, because they can affect urine and ECG results. Arrive 10 minutes early. That is the practice's published advice, restated here, and it is marked for the doctor to confirm before any new "avoid" rule is added.`},{t:"confirm",x:'Please confirm that the "night before" list (rest, and avoid caffeine, tobacco and high-sugar meals) is still what the practice wants said. Default: no added rules, and no routine pre-visit blood tests.'},{t:"p",x:"Do not start, stop or hide a medicine the night before in order to influence the exam. Ask your treating doctor before you change anything, and tell the examiner what you take."},{t:"h2",x:"What to bring",id:"what-to-bring"},{t:"ul",items:["Proof of identity (ID or passport)","Your completed SACAA form, if you have not already submitted it","Your licence and last medical certificate, if you have them","A list of medicines, including pharmacy products","Your glasses or contact lenses, and a spare pair if you have one","Your medical aid card, if you use one","Any recent specialist or optometrist reports that are relevant"]},{t:"p",x:"The full checklist is on the [aviation medicals page](/aviation-medicals/) and the Midrand post."},{t:"h2",x:"What not to do",id:"what-not-to-do"},{t:"p",x:"Do not conceal history. Incomplete disclosure is itself a problem. Do not arrive without a booking; the practice is by appointment only. Do not expect a Class 1 medical here. Do not invent a set of last-minute tricks. If you forget a document, call 011 568 7979 or WhatsApp 078 255 1405 before you travel, and ask whether the visit can still go ahead."},{t:"confirm",x:"Please confirm the practice's stance if someone arrives without their last certificate."},{t:"h2",x:"First medical versus renewal",id:"first-medical-versus-renewal"},{t:"p",x:"A first medical and a straightforward renewal use the same form and the same honesty rule. First-time student pilots may also want the live [student pilot guide](/blog/student-pilot-medical-south-africa/). Renewal periods themselves are explained in the [validity post](/blog/class-2-medical-validity-by-age/). If something has changed in your health, say so, even if your last visit was uneventful."},{t:"p",x:"If a previous medical was deferred, bring the reports that were requested, and read [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/) so you know the process. If you are travelling from Pretoria or Centurion, the [location guide](/blog/aviation-medical-pretoria-centurion/) has the Midrand address and booking path."},{t:"p",x:"When you are ready, complete the [form](/sacaa-form/) and [book a Class 2 or Class 4 medical](/book/), or call 011 568 7979 or WhatsApp 078 255 1405."},{t:"cta",x:"Complete the form and book your Class 2 or Class 4 medical"}],faq:[{q:"How do I prepare for my first aviation medical?",a:"Complete the form, gather your documents, rest, and bring a list of medicines."},{q:"Can coffee or energy drinks affect the results?",a:"The live site says to avoid caffeine beforehand because it can affect urine and ECG results. That wording is marked for the doctor to confirm."},{q:"What if I forget my last certificate?",a:"Call before you travel. The practice's stance is marked for confirmation."},{q:"Should I have blood tests done first?",a:"Only if your history already requires them, or the practice asked you to. This article does not invent a routine panel."},{q:"I am renewing and nothing has changed. Do I still need the form?",a:"Yes."},{q:"How do I book?",a:"Online at the booking page, or by phone or WhatsApp."}],sources:[e.form]},A={slug:"foreign-licence-conversion-sacaa-medical",title:"Foreign Licence Conversion: The Medical Step | ClinoTrend",h1:"Converting a foreign pilot licence: what the SACAA medical involves",description:"What medical you need when converting a foreign licence to a SACAA licence, who can do the exam, and what to bring. This is not a full conversion guide.",excerpt:"The SACAA medical step when converting a foreign licence: which class you need, who can do the exam, and what to bring. This is not a full conversion guide.",keyword:"foreign licence conversion sacaa medical",question:"What medical do I need when converting a foreign pilot licence to a SACAA licence?",answer:"A foreign medical certificate does not replace a SACAA medical when the South African rules require one. The class you need follows the SACAA licence you are applying for, not the name of the foreign class. ClinoTrend can do Class 2 and Class 4 medicals. Class 1 conversions need a Senior DAME.",facts:["A foreign medical certificate does not replace a SACAA medical when the South African rules require one.","The class follows the SACAA licence you are applying for, not the name of the foreign class.","ClinoTrend can do Class 2 and Class 4 medicals. Class 1 conversions need a Senior DAME."],secondary:["faa medical conversion south africa","icao medical certificate south africa","convert foreign pilot licence south africa","sacaa medical for foreign licence"],published:"2026-11-11",updated:"2026-11-11",status:"draft",tag:"Conversion",body:[{t:"note",x:'Primary keywords "foreign licence conversion sacaa medical" and "faa medical conversion south africa". Volume: no volume source. Source: exact phrases returned no Google Autocomplete suggestions on 10 November 2026 (gl=za). The topic is still a real conversion job. Supporting term "icao medical certificate south africa" also had no suggestions in that check (no volume source). Ruben can run the Keyword Planner upload file and send the export back.'},{t:"p",x:"This page covers the medical step only. It is not a conversion or validation manual for licences, exams or hours."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"If you are converting, or seeking to validate, a foreign licence in South Africa, the licensing process and the medical process are separate. This practice does the medical only, and only for Class 2 and Class 4. Licence exams, hour requirements and conversion forms sit with SACAA personnel licensing, not with a DAME blog post."},{t:"h2",x:"Licence process versus medical process",id:"licence-process-versus-medical-process"},{t:"p",x:"Use the current SACAA personnel licensing pages for conversion or validation of a foreign licence. The exact URLs on the SACAA site can change, so start from the Authority's public site and the personnel licensing section, rather than from a copied link that may go stale. This article does not guess a form number or a conversion checklist. Ask the licensing department which medical class your application requires, then book that class with an examiner who is designated for it."},{t:"h2",x:"Which class you are likely to need",id:"which-class-you-are-likely-to-need"},{t:"p",x:"The class follows the SACAA licence, not the name of your foreign medical (FAA first class, EASA class 1, and so on). In outline:"},{t:"ul",items:["A South African private pilot licence is usually supported by a Class 2 medical.","A commercial or airline transport licence is supported by a Class 1 medical, which only a Senior DAME can issue. See [SACAA Class 1 medical and Senior DAMEs](/blog/sacaa-class-1-medical-senior-dame/).","Cabin crew medicals are Class 4, as explained in the live [cabin crew post](/blog/cabin-crew-medical-class-4-south-africa/)."]},{t:"p",x:"Confirm the class with the licensing department. Validation (temporary recognition of a foreign licence) and full conversion are not the same process, and this article does not invent a medical exception for either route."},{t:"confirm",x:"Please confirm any difference in the medical step between validation and full conversion, and whether first-issue medical rules always apply to a conversion applicant."},{t:"h2",x:"What to bring",id:"what-to-bring"},{t:"ul",items:["Your foreign licence and last medical certificate","Your passport or other proof of identity","Any specialist reports and a medicine list","The completed [SACAA application form](/sacaa-form/)","Your last South African certificate, if you already have one"]},{t:"p",x:"[Book a Class 2 or Class 4 medical](/book/) only if that is the class your application requires. For a confirmed fee, which starts from R1,500, see [how much a SACAA aviation medical costs](/blog/aviation-medical-cost-south-africa/), or call 011 568 7979 or WhatsApp 078 255 1405."},{t:"h2",x:"What does not carry over automatically",id:"what-does-not-carry-over-automatically"},{t:"p",x:'SACAA applies its own standards, validity periods and examiner categories. The [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/) states that SACAA complies with ICAO Annex 1, Chapter 6. That is a statement about the South African standard. It is not a statement that an ICAO-format or foreign medical certificate can be used in place of a SACAA certificate when a SACAA certificate is required. Do not treat an FAA, EASA or UK medical as "counting as" a SACAA Class 1 or Class 2.'},{t:"h2",x:"What ClinoTrend can do, and what it cannot",id:"what-clinotrend-can-do-and-what-it-canno"},{t:"p",x:"Dr A.O. Ndhlovu is a Regular DAME, MR 336, at Grand Central Airport, Midrand, and issues Class 2 and Class 4 only. If your application needs Class 2 or Class 4, you can book here. If it needs Class 1, you need a Senior DAME. The practice issues the medical certificate and the medical report. It does not complete a whole conversion file for the licensing department, unless the doctor later confirms a wider service."},{t:"confirm",x:"Please confirm that the practice issues the medical certificate and report only, and does not complete licensing conversion forms, and whether you want to be found for this audience."},{t:"cta",x:"Book a Class 2 or Class 4 medical, if that is the class you need"}],faq:[{q:"Can I use my FAA or EASA medical in South Africa instead of a SACAA one?",a:"Not when a SACAA certificate is required. Follow the official conversion or validation rules, not a blog shortcut."},{q:"Which class do I need to convert a PPL?",a:"Usually Class 2, if that is the SACAA licence you are applying for. Confirm with the licensing department."},{q:"I need a Class 1 for a CPL conversion. Can I come to ClinoTrend?",a:"No. You need a Senior DAME."},{q:"Do I need to start from a first-issue medical?",a:"This is marked for the doctor to confirm."},{q:"How much does it cost?",a:"From R1,500 for a Class 2 or Class 4 medical here. The fee is confirmed when you book."},{q:"Can the practice fill in licensing forms?",a:"The default is the medical certificate and report, not the whole conversion file. That is marked for confirmation."}],sources:[e.avmed,e.classesReg,e.register]},C=[c,h,m,u,f,p,y,g,A],w=[i,t,o,s,l,n,r,d,...C];w.filter(a=>a.status==="approved");const b=a=>`/blog/${a.slug}/`,v=[{name:"Home",path:"/"},{name:"Blog",path:"/blog/"}];export{v as B,w as P,e as S,b as p};
